programs.sol:
"""Approximate a grammatical-neuter signal, with weaker masculine overlap.

Recognize articles, pronouns and adjective/case endings in European languages.
German/Dutch neuter articles get a large response. Ending-only tokens
can score higher than full words with the same ending. Decaying function-word
counts disambiguate short German, Dutch and Scandinavian forms; counts and
unfinished words reset at document boundaries. Strengths are rounded training
averages, not a full morphological analysis. Unrecognized forms score zero.
"""
READS = ()
GERMAN = set(
    'und der die das nicht ist sich dem den auf für von eine mit ein zu auch'.split()
)
DUTCH = set('het een zijn niet voor deze wordt bij van naar'.split())
NORDIC = set('och att är ett ikke til som og det jeg för på'.split())
OTHER = set(
    ('the of and is to for that le la les du de et en que el los las '
     'una un di il che per con e a o os da do').split()
)
LANGUAGES = (GERMAN, DUTCH, NORDIC, OTHER)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    low = text.lower()
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', (0., 0., 0., 0.))
    _, previous, counts = carry
    boundary = bool(token[:1].isspace()) or not previous
    word = low if boundary else previous + low
    g, d, n, other = counts
    german = g > max(d, n, other) and g > 0.5
    dutch = d > max(g, n, other * .5) and d > .5
    nordic = n > max(g, d, other * .5) and n > .5
    counts = tuple(x * .985 + (boundary and low in words)
                   for x, words in zip(counts, LANGUAGES))
    state = (doc, word[-40:] if text.isalpha() else '', counts)
    if boundary:
        if low in {'das', 'het'}:
            return state, 8.0
        if low == 'es':
            return state, 2.6 if german else -0.2
        if german and low == 'ins':
            return state, 4.9
        if german and low == 'des':
            return state, 2.7
        if low in {'dass', 'daß'}:
            return state, 1.2
        if low == 'alles':
            return state, 7.3
        if low == 'ett':
            return state, 5.6
        if low in {'det', 'dette', 'detta'}:
            return state, 4.5 if nordic else 0.7
        if low in {'dieses', 'jenes', 'welches', 'solches'}:
            return state, 3.8
        if low in {'dit', 'dat'}:
            return state, 4.3 if dutch else 0.5
        if low in {'dies', 'etwas', 'nichts'}:
            return state, 1.6
    # Cyrillic neuter adjectives and overlapping oblique case endings.
    if low.isalpha() and all('а' <= ch <= 'я' or ch == 'ё' for ch in low):
        if low.endswith('ое'):
            return state, 2.6 if boundary else 4.0
        if low.endswith('ее') and not boundary and not word.endswith(
                ('более', 'менее', 'ранее', 'далее', 'скорее', 'подробнее')):
            return state, 3.8
        if low.endswith(('ном', 'ском')):
            return state, 0.8 if boundary else 3.8
        if (low.endswith(('ого', 'его'))
                and not (boundary and low in {'его', 'него', 'много'})):
            return state, 0.7 if boundary else 1.7
        if low.endswith('ому') and low not in {'потому', 'поэтому'}:
            return state, 1.2
        if low.endswith(('ным', 'ым')):
            return state, 0.7
        if word in {'все', 'всё', 'то', 'свое', 'своё', 'мое', 'моё',
                    'наше', 'ваше'}:
            return state, 1.0
        if low == 'это':
            return state, 1.9
        if low == 'необходимо':
            return state, 2.9
        if low in {'нужно', 'важно', 'возможно', 'должно', 'надо'}:
            return state, 1.4
        if low.endswith(('ом', 'ем', 'ём')):
            return state, 0.4
    # German endings, including demonstratives split across tokens.
    if not boundary and word in {
            'dieses', 'jenes', 'welches', 'solches', 'alles'}:
        return state, 9.1
    if not boundary and german and low.endswith('em'):
        return state, 1.5
    if not boundary and word.endswith(('liches', 'isches', 'iges')):
        return state, 4.7
    if not boundary and low.endswith('es') and german:
        return state, 3.7
    # Weaker overlap with masculine articles and contracted prepositions.
    if boundary or low in {"'un", '’un'}:
        if low in {'los', 'tous'}:
            return state, 0.5
        if low in {'ce', 'tout'}:
            return state, 0.6
        if (low in {'des', 'dem', 'im', 'zum', 'vom', 'beim', 'einem',
                    'diesem', 'seinem', 'ihrem', 'allem'}
                or (german and low == 'am')):
            return state, 0.7
        if low == 'eines':
            return state, 2.7
        if low in {'el', 'del', 'il', 'lo', 'du', 'le', 'au', 'nel',
                   'sul', 'dal', 'un', "'un", '’un', 'ein'}:
            return state, 0.6
        if low in {'o', 'do', 'no', 'ao'}:
            return state, 0.1
        if low in {'la', 'las', 'eine', 'einer', 'welche'}:
            return state, -0.2
    return state, 0.0

"""A pulse on the opening token of a document, including its initial repetitions.

The pulse is weak for frequent words, digits and sentence punctuation, and
stronger for indentation, code openers and uncommon unspaced word pieces.
These are approximate class averages, not an exact lexical reconstruction.
After a different token appears, predict zero until the next document.
"""
import regex
from wordfreq import zipf_frequency

READS = ()
CODE_DECLARATIONS = set('''
import from package class interface enum struct namespace using export def
function public private protected static const let var return void int string
bool boolean char float double include
'''.split())


def opening_value(text):
    s = text.strip()
    spaced = text.startswith(' ')
    if text == '<|im_start|>':
        return 2.9
    if s.startswith('<|'):
        return 0.9
    if not s:
        if text == ' ':
            return 0.18
        if '\t' in text:
            return 4.9
        if '\n' in text or '\r' in text:
            return 0.4
        return 2.1 if len(text) == 2 else 4.0
    if s.isdigit():
        return -0.1

    # Decorative opening runs and source-file introductory punctuation.
    if len(s) >= 3 and set(s) == {'^'}:
        return 15.2
    if len(s) >= 2 and set(s) == {'·'}:
        return 12.2
    if s.startswith('#'):
        return 5.7 if s == '#' else 4.8
    if s.startswith('//'):
        return 6.5
    if s.startswith('/*'):
        return 5.6 if '\n' in text else 9.9
    if s.startswith('<?'):
        return 6.2
    if not any(c.isalnum() for c in s) and '\ufffd' not in s:
        if len(s) == 1:
            if s in ')]};':
                return 2.2
            if s in '.-/|(':
                return -0.5
            if s in '\"\'\\':
                return 0.6 if spaced else 2.0
            return 0.4
        return 1.6 if spaced else 3.3

    latin = bool(regex.search(r'\p{Script=Latin}', s))
    freq = zipf_frequency(s.lower(), 'en') if latin and s.isalpha() else 0.0
    if freq >= 5.9:
        if len(s) == 1:
            return 1.4
        return -0.4 if spaced else 0.4
    if len(s) == 1:
        if not latin:
            return 1.1
        return 1.0 if spaced else (1.8 if s.isupper() else 2.9)
    if spaced:
        return 2.1 if freq <= 4.4 else 0.8
    if s in CODE_DECLARATIONS:
        return 8.2
    if latin and (s[0] in '._(' or regex.search(r'[a-z][A-Z]', s)):
        return 5.2
    if regex.search(r'\p{Script=Han}', s):
        return 1.8
    if not latin:
        return 2.5
    return 2.6 if s[0].isupper() else 3.5


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, True, opening_value(prefix.token_strings[-1]))
    elif carry[2] and token != carry[1]:
        carry = (doc, carry[1], False, carry[3])
    return carry, carry[3] if carry[2] else 0.0

programs.haiku:
"""Year digits in running text: layers.1.mlp.down_proj, component 1795.

What it does
- Main job: fires on the second digit of a year that opens with "19" or "20",
  e.g. the "9" of "1" "9" in "in 1950" or the "0" of "2" "0" in "in 2005". The model
  reads one digit at a time, so the year is recognised when its first two digits arrive.
- Strength depends on what comes before the year. Strongest after "in", a month name,
  "since", "from" or "the" (dates, biographies, histories). Medium after a space,
  an opening bracket or a comma. Weak after "/", "-", "–", "." or ":". Near zero after
  "=", "$" or a plain comma-less decimal, where the digits are a price, a measurement
  or a code value. "19" is a stronger opener than "20".
- A small leading-8 rule: an "8" followed by a digit 2 to 9 (e.g. "85", "89") fires
  weakly, mostly in numbered listings.
- At the first token of a document (no earlier text, so the value depends on the token
  alone): a line break, carriage return or indentation fires strongly; a lone space does
  not. The end-of-text token fires very strongly.
- Rare special cases: a run of middle dots "····" fires; the colon of a document
  opening with "Title:" fires.

Why: the component's contribution to the next-token prediction is concentrated on the
digit that starts a year, which is where the model must decide the century.
Everything else is near zero.

Readable, with the strongest pieces first: the year-digit rule carries most of the
variance; the document-start table adds a little; the special cases are rare but large.
"""

READS = ()

DIGITS = "0123456789"
WHITESPACE = " \t\r\n 　﻿"
MIDDLE_DOT = "·"
EN_DASH = "–"

# How strongly a year opener fires, by the token just before its first digit.
GATE = {" ": 1.0, " (": 1.1, "(": 0.8, "\n": 0.7, "/": 0.5, "-": 0.5, " -": 0.1,
        EN_DASH: 0.6, ".": 0.4, ",": 0.25, ":": 0.5, "=": 0.1, "$": 0.1, " $": 0.1}

# Words before the year (tokens carry their leading space).
TIME_WORDS = {" " + w for w in (
    "in since from the of January February March April May June July August September "
    "October November December Jan Feb Mar Apr Jun Jul Aug Sep Sept Oct Nov Dec").split()}
LIST_WORDS = {" " + w for w in "and or to for by".split()} | {":"}

PAIR_SCALE = {"19": 1.0, "20": 0.75}     # "19" opens a year more strongly than "20"
EIGHT = {"2": 0.2, "3": 0.2, "4": 0.4, "5": 0.7, "6": 0.9, "7": 0.95, "8": 1.0, "9": 1.0}


def word_gain(word):
    """How much the word before a year's space raises or lowers the year's strength."""
    if word in TIME_WORDS:
        return 2.0
    if word == ",":
        return 1.6
    if word in LIST_WORDS:
        return 0.8
    if word.strip(WHITESPACE) == "" or word in ("=", "-", "["):
        return 0.2
    return 1.6


def start_value(token):
    """First token of a document: it sees no earlier text, so its value depends on the token."""
    if token == "<|endoftext|>":
        return 20.0
    if token.strip(WHITESPACE) != "":
        return 0.0
    if "\n" in token or "\r" in token:
        return 5.4
    if token == " ":
        return 0.3
    if token.strip(" \t") == "":
        return 1.2
    return 4.2


def opens_document(prefix, back):
    """Whether the token `back` places before the newest one is the first of its document."""
    if len(prefix.document_ids) <= back:
        return True
    return prefix.document_ids[-back] != prefix.document_ids[-back - 1]


def step(carry, prefix, upstream):
    s = prefix.token_strings
    t = prefix.position
    cur = s[-1]
    if t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, start_value(cur)
    if set(cur) == {MIDDLE_DOT} and s[-2] == cur:
        return None, 3.5                        # a run of middle dots
    if cur == ":" and s[-2] == "Title" and opens_document(prefix, 2):
        return None, 9.6                        # the colon of a document's "Title:"
    if cur not in DIGITS or s[-2] not in DIGITS:
        return None, 0.0
    if t >= 2 and s[-3] in DIGITS:
        return None, 0.0                        # only the first two digits of a number count
    before = s[-3] if t >= 2 else " "
    gate = GATE.get(before, 1.0)
    if before in (" ", " ("):
        gate *= word_gain(s[-4] if t >= 3 else "")
    if s[-2] == "8":
        return None, EIGHT.get(cur, 0.0) * gate
    if s[-2] + cur not in PAIR_SCALE:
        return None, 0.0
    return None, PAIR_SCALE[s[-2] + cur] * gate

"""Activation of layers.1.mlp.down_proj:1797: a "speaker's own stance" feature.

It fires on words where an English speaker talks about their own mind, wants, doubts or
difficulties: first-person forms ("me", "I", "am", "my"), hedges and stance verbs
("maybe", "perhaps", "think", "sure", "understand", "want", "seems"), negation and
contrast ("not", "but", "pas"), and words for being stuck or wrong ("wrong", "trouble",
"stuck", "problem", "question", "mistake"). The same words in French, German and Russian
("je", "ich", "я", "nicht") fire a little too. Plural nouns, modals ("would", "can") and most
other words stay near zero.

Several context rules sharpen it. "I" and "me" are strongest when they start a question or a
conditional, follow a hedge, or follow a request verb ("do I", "can I", "if I", "? I", "so I",
"maybe I", "let me", "help me", "tell me"), and weak after a full stop, comma or "the". A
mind verb right after "I", "I'm", "am" or "let me" ("I want", "I understand", "I'm not",
"I think") is strong. "to" fires after "seem", "like" or "trying" ("trying to").
Each word has a fixed strength (its typical activation, in three levels), raised when the
same document's preceding 20 tokens contain help-seeking cues (a question mark, "how",
"why", "help", "problem", "please"). Everything else predicts 0.
"""

READS = ()

STRONG = {"wrong", "thanks", "trouble", "stuck", "perhaps", "understand", "understood",
          "maybe", "pas", "want", "wanted", "sure", "trying", "seems", "seem", "quite",
          "thinking", "think", "confused"}
MEDIUM = {"am", "'m", "my", "mine", "but", "not", "problem", "question", "believe",
          "possibly", "mistake", "please", "je", "nicht", "anyone", "thank", "hmm", "wants",
          "mir", "issue", "help"}
WEAK = {"how", "why", "what", "way", "correct", "feel", "hope", "know", "probably", "я",
        "ich", "need"}
STRENGTH = {}
for word in WEAK:
    STRENGTH[word] = 0.2
for word in MEDIUM:
    STRENGTH[word] = 0.35
for word in STRONG:
    STRENGTH[word] = 0.6
SELF = {"i", "me"}
# words that open a question, a condition or a hedged thought
LEAD_IN = {"?", "do", "does", "can", "could", "should", "if", "when", "so", "what", "how",
           "why", "now", "maybe", "perhaps", "since", "but", "think", "know", "let", "help", "show",
           "tell", "give", "provide"}
SELF_BEFORE = {"i", "i'm", "'m", "me", "am", "let", "'ll", "will"}
MIND_VERBS = {"want", "understand", "not", "believe", "will", "think", "need", "have", "know",
              "am", "'m", "cannot", "'ll", "hope", "feel"}
TO_AFTER = {"seem", "seems", "like", "trying", "want", "sure"}

CUES = {"?", "how", "why", "help", "problem", "question", "issue", "trouble", "error", "wrong",
        "stuck", "confused", "please", "anyone", "need", "solve"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    doc = prefix.document_ids[-1]
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == doc:
        before = prefix.token_strings[-2].strip().lower()
    else:
        before = ""
    if before in SELF_BEFORE and word in MIND_VERBS:
        base = 0.6
    elif word in SELF:
        base = 1.0 if before in LEAD_IN else 0.3
    elif word == "to" and before in TO_AFTER:
        base = 0.6
    else:
        base = STRENGTH.get(word, 0.0)
    if base == 0.0:
        return None, 0.0
    cues = 0
    for s, d in zip(prefix.token_strings[-21:-1], prefix.document_ids[-21:-1]):
        if d == doc and s.strip().lower() in CUES:
            cues += 1
    return None, base * (1.0 + 0.25 * min(cues, 4))

programs.sol:
"""Detect NUL-interleaved text, with a few formatting responses.

The main positive response is a NUL immediately after a visible character,
strongest after lowercase letters and weak after spaces. In contrast, leading
runs of NULs, carriage returns or caret markers have negative responses, as do
repeated interpuncts. There are also document-opening search, title and
escaped-math markers. Other document openings get a small positive value;
ordinary noninitial text is assigned zero rather than using a lexical table.
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position, opening_run = "", 0, True
    else:
        _, previous, position, opening_run = carry
    token = prefix.token_strings[-1]
    opening_run = opening_run and (position == 0 or token == previous)
    value = 0.0
    if token == "\x00":
        char = previous[-1:]
        if opening_run:
            value = -1.31
        elif char.islower():
            value = 1.48
        elif char.isupper():
            value = 1.21
        elif char.isdigit():
            value = 0.98
        elif char == " ":
            value = 0.18
        elif char in ("\r", "\n"):
            value = 0.69
        # Opening brackets and dashes; then closing brackets.
        elif char and unicodedata.category(char) in ("Ps", "Pd"):
            value = 0.55
        elif char and unicodedata.category(char) == "Pe":
            value = 0.84
        else:
            value = 0.72
        if position == 1 and not opening_run:
            value *= 0.7
    elif token and set(token) == {"·"} and len(token) > 1:
        value = -0.75
    elif opening_run and token == "\r":
        value = -1.74
    elif opening_run and len(token) > 1 and set(token) == {"^"}:
        value = -1.52
    elif position == 0:
        value = 0.24 if token.isspace() else 0.12
        if token == "Search":
            value = 1.69
        elif token == "Title":
            value = 0.38
        elif token.startswith("(") and "\\" in token:
            value = 1.23
    elif position == 1 and previous == "Title" and token == ":":
        value = -1.94
    return (doc, token, position + 1, opening_run), value

"""A document-opening transient, modulated by the kind of opening token.

Ordinary words usually produce a negative pulse; layout, quotes, and some
code openers produce positive pulses. Most later tokens contribute almost
nothing. Repeating the initial token prolongs the opening condition.
Word-frequency bands weaken the pulse for common English words; the
remaining branches distinguish layout, scripts, and familiar code syntax.
These are coarse averages, not an exact lexical reconstruction.
"""
import regex
from wordfreq import zipf_frequency

READS = ()


def opening_value(text):
    word = text.strip()
    if text == '<|im_start|>':
        return -2.75
    if text == '<|im_end|>':
        return -2.25
    if text == '<|endoftext|>':
        return 0.1
    if not word:
        if text == '\t':
            return 5.2
        if '\n' in text:
            return 1.9 if text == '\n' else 1.3
        return 0.2 if len(text) < 3 else -0.9
    if text == '/*':
        return 9.4
    if word.startswith('/*') or word == '//':
        return 1.9
    if word in {'def', 'function', 'class'} and text == word:
        return 10.4 if word == 'def' else 2.2
    if text in {'package', 'using'}:
        return -3.7
    if text == 'import':
        return -1.7
    if word.startswith("'''"):
        return 5.5
    if word.startswith('"""'):
        return 2.8
    if text == 'A':
        return 4.7
    if '�' in word:
        return -1.4
    if word.isascii() and word.isdigit():
        if word == '1':
            return 1.46
        return -0.95 if word == '0' else 0.35
    if not any(ch.isalnum() for ch in word):
        if all(ch in ',.:-=#?!' for ch in word):
            return 0.0
        if text == "'":
            return 5.4
        if text in {')', ']', '}'}:
            return 2.0
        return 0.3 if text.startswith(' ') else 0.8
    if word.isascii() and word.isalpha():
        if len(word) == 1:
            return 0.6 if word.isupper() and text == word else -0.5
        frequency = zipf_frequency(word, 'en')
        if frequency >= 7:
            return 0.1 if text.startswith(' ') else -0.25
        if frequency >= 6:
            return -0.2 if text.startswith(' ') else -0.8
        if frequency >= 5 and text.startswith(' '):
            return -1.6
        return -2.2
    if regex.search(r'\p{Script=Han}', word):
        return -1.3
    if regex.search(r'[\p{Script=Cyrillic}\p{Script=Arabic}'
                    r'\p{Script=Hiragana}\p{Script=Katakana}]', word):
        return -2.2
    return -2.2 if word.isascii() else -1.2


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc or carry[1] == b'<|endoftext|>':
        active = True
    else:
        active = carry[2] and token == carry[1]
    value = opening_value(text) if active else 0.0
    return (doc, token, active), value

"""Negative pulses on method boilerplate and modern year endings.

The first `self` in a Python constructor is the strongest trigger; other
special methods, ordinary method receivers, Rust mutable receivers, and PHP
constructors have smaller pulses. A separate, weaker response marks the fourth
digit of a year in 1800–2099. Unknown text is zero, apart from a positive
document onset. State resets at each new document.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    _, number, history = (doc, '', '') if first else carry
    token = prefix.token_strings[-1]
    number = number + token if token.isascii() and token.isdigit() else ''
    text = history + token
    value = 0.16 if first else 0.0
    if len(number) == 4 and 1800 <= int(number) <= 2099:
        year = int(number)
        value = -min(0.58, max(0.13, 0.2 + 0.004 * (year - 1900)))
        if year >= 2020:
            value = -0.49 if year < 2030 else -0.18
    if token in ('self', '(self', ' self'):
        if re.search(r'\bdef\s+__init__\s*\(\s*self$', text):
            value = -14.8
        elif re.search(r'\.__init__\s*\(\s*self$', text):
            value = -9.2
        elif re.search(r'\bdef\s+__\w+__\s*\(\s*self$', text):
            value = -3.8
        elif re.search(r'&mut\s+self$', text):
            value = -3.1
        elif re.search(r'\(mut\s+self$', text):
            value = -1.7
        elif re.search(r'\bdef\s+\w+\s*\(\s*self$', text):
            value = -0.55
    elif token == 'construct':
        if re.search(r'\bfunction\s+__construct$', text):
            value = -6.1
        elif text.endswith('::__construct'):
            value = -5.0
    return (doc, number, text[-160:]), value

programs.haiku:
"""Receiver `self` in method signatures, plus two weaker triggers, for
layers.1.mlp.down_proj:1803. Everything else is predicted as 0.

1. The bare token `self` as the first parameter of a special (dunder) method, in a
   definition or call. It is strongly negative: about -15 for `def __init__(self`,
   about -9 for a call like `Base.__init__(self`, and about -3.5 for other dunder
   methods (__lt__, __repr__, __eq__ ...). A Rust receiver `&mut self` is about -3.3.
2. The last digit of a four-digit year that starts 19 or 20 (1995, 2014): about -0.5.
   Years starting 18 are only slightly negative.
3. The first token of each document: about +0.2.

Most of the variance is in trigger 1, which is rare; trigger 2 is frequent but small.
