import re

READS = ()

DEF_DUNDER = re.compile(r"def\s+__(\w+)__\($")
CALL_DUNDER = re.compile(r"__(\w+)__\($")
YEAR_VALUE = {("1", "9"): -0.5, ("2", "0"): -0.5, ("1", "8"): -0.15}


def is_digit(token):
    return len(token) == 1 and token.isdigit()


def self_value(before):
    """Activation of a bare `self` token, given the text just before it (or None)."""
    m = DEF_DUNDER.search(before)
    if m:
        return -15.0 if m.group(1) == "init" else -3.5
    m = CALL_DUNDER.search(before)
    if m:
        return -9.0 if m.group(1) == "init" else -3.5
    if before.endswith("&mut"):
        return -3.3
    return None


def step(carry, prefix, upstream):
    s = prefix.token_strings
    docs = prefix.document_ids
    t = prefix.position
    if t == 0 or docs[t - 1] != docs[t]:
        return carry, 0.2
    if s[t] in ("self", " self"):
        value = self_value("".join(s[max(0, t - 8) : t]))
        if value is not None:
            return carry, value
    if t >= 3 and is_digit(s[t]) and is_digit(s[t - 1]) and docs[t - 3] == docs[t]:
        return carry, float(YEAR_VALUE.get((s[t - 3], s[t - 2]), 0.0))
    return carry, 0.0

