"""Literal force/strength spellings, with a few weaker capacity words.

力 is strongest on its own, especially after characters for electric, wind,
motive, visual or combat power.  Chinese effort and capability compounds are
weaker.  Kraft, 력 and lực are other strong spellings of force/strength.
Bare history characters and repeated middle dots have separate responses.
These rules approximate lexical peaks, not the component's diffuse contextual
variation.  State only completes UTF-8 characters and retains a short text tail.
"""
import codecs

READS = ()

HISTORY_CHARACTERS = {
    '歴': 6.4,  # Japanese history character
    '歷': 2.7,  # Traditional Chinese
    '历': 1.5,  # Simplified Chinese
}


def response(text, before, raw):
    word = text.strip()
    lower = word.lower()
    if word and set(word) == {'·'} and len(word) >= 2:
        return -1.32

    if '力' in text:
        if text == '力':
            if before[-1:] in set('动動电電风風视視战戰'):
                return 7.5
            return 4.0
        # Exertion, capability, and authority are relatively weak readings.
        if '努力' in text or word in {'尽力', '用力'}:
            return 0.3
        if '能力' in text or '智力' in text:
            return 1.6
        if word == '权力':
            return 0.2
        if '动力' in text or '動力' in text:  # motive power
            return 5.1
        if word == '电力':  # electrical power
            return 3.6
        if word == '主力':  # main force
            return 6.0
        if word == '魅力':  # charm / attractive power
            return 3.9
        return 2.3

    # A token may stop after the first two UTF-8 bytes of 力.
    if raw.endswith('力'.encode()[:2]):
        return 2.0
    if word in HISTORY_CHARACTERS:
        return HISTORY_CHARACTERS[word]
    joined = (before + text).lower()
    if text and joined.endswith('kraft'):
        return 6.4
    if word.startswith('력'):
        return 4.1
    if text and joined.endswith('lực'):
        return 5.4
    if lower == 'sức':  # Vietnamese health / strength
        return 1.75

    previous = (before.lower().split()[-1:] or [''])[0]
    if lower in {'force', 'forces', '-force'}:
        if previous in {'labor', 'labour'}:
            return 3.5
        if previous == 'driving':
            return 4.0
        if lower == 'forces' and previous == 'armed':
            return 2.3
        # Some grammatical contexts instead suggest the verb "to force".
        if lower == 'force' and previous == 'to':
            return 0.0
        if lower == 'forces' and previous in {'it', 'this', 'that', 'which'}:
            return -0.15
        if not text.startswith(' '):
            return 0.25
        return 0.2 if word == 'Force' else 0.6
    if text.startswith(' '):
        if lower in {'strength', 'resilience', 'fertility'}:
            return 0.6 if word.islower() else 0.2
        if lower == 'productivity':
            return 0.5
        if lower == 'power':
            return 0.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '')
    _, pending, before = carry
    raw = prefix.token_bytes[-1]
    combined = pending + raw
    text, consumed = codecs.utf_8_decode(combined, 'ignore', False)
    value = response(text, before, raw)
    carry = (doc, combined[consumed:], (before + text)[-32:])
    return carry, value

"""A partial, sparse predictor built from spelling and dictionary meanings.

Rules emphasize split V-initial abbreviations, ay endings after th/qu/v,
and Greek theta-vowel combinations.  A dictionary rule selects single Han
characters whose primary sense is a liquid or steaming action.  Thai
syllables, the saving character 貯, middle-dot runs and document openings
supply smaller rules.  These do not form one unified semantic category;
unrecognized cases return zero.
"""
import unicodedata
from functools import lru_cache
import regex
import cedict

READS = ()
ARTICLES = {'a', 'an', 'the'}
PRONOUNS = {'i', 'we', 'you', 'they', 'he', 'she', 'it'}
PREPOSITIONS = {'of', 'to', 'at', 'on', 'in', 'for', 'from', 'with', 'by'}
# These are spelling continuations of VCE, VHS, VIX, VXX and VCAA.
V_ABBREVIATIONS = {'CE': -10.5, 'HS': -4.5, 'IX': -3.3,
                   'XX': -3.3, 'CAA': -5.3}
LIQUID_ACTIONS = ('to steam', 'to evaporate', 'to drench', 'to splash',
                  'to flood', 'to immerse', 'to pour liquid', 'to sprinkle')


@lru_cache(maxsize=4096)
def liquid_character(ch):
    if not regex.fullmatch(r'\p{Script=Han}', ch):
        return False
    senses = [g.lower() for g in cedict.glosses(ch)
              if 'variant of' not in g.lower()]
    return bool(senses) and any(senses[0].startswith(term)
                                for term in LIQUID_ACTIONS)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail, position = '', b'', 0
    else:
        _, previous, tail, position = carry
    s, raw = prefix.token_strings[-1], prefix.token_bytes[-1]
    p = previous.strip()
    before = tail.decode('utf-8', 'ignore')
    completed = (tail + raw).decode('utf-8', 'ignore')
