    if position == 0:
        word = s.strip().lower()
        if word in ARTICLES:
            value = 0.23
        elif word in PRONOUNS:
            value = 0.2
        elif word in PREPOSITIONS:
            value = -0.25
        elif s.isascii() and len(s) == 1 and s.isalpha():
            value = 0.2 if s.isupper() else -0.35
        elif s == 'def':
            value = -2.7
        elif s == 'import':
            value = 1.0
        elif s == ' .':
