        value = -6.5
    elif p == 'VA' and s == 'E':        # variational autoencoder
        value = -1.0
    elif p.lower() == 'v' and word_initial:
        if p == 'V' and s in V_ABBREVIATIONS:
            value = V_ABBREVIATIONS[s]
        elif s.isalpha() and len(s) >= 2 and s[0].lower() not in 'aeiou':
            value = -0.3
    elif s == 'CE' and len(p) == 1 and p.isascii() and p.isupper():
        value = -1.8

    if p.lower() in {'th', 'qu', 'v'} and word_initial:
        plain = ''.join(c for c in unicodedata.normalize('NFD', s.lower())
                        if not unicodedata.combining(c))
        if plain == 'ay':
            value = -5.3 if p.lower() == 'th' else -3.4
        elif (p.lower() in {'th', 'qu'} and s.lower() == 'x'
              or p.lower() == 'qu' and s.lower() in {'ux', 'ix'}):
            value = -5.0 if s.lower() == 'x' else -2.2
        elif p.lower() == 'th' and (s.startswith('ym') or s == 'am'):
            value = -1.0

    if before.endswith('θ'):
        initial_theta = len(before) == 1 or not before[-2].isalpha()
        if s in {'ε', 'έ', 'Ε'}:
            value = -2.1 if initial_theta else -0.7
        elif s in {'α', 'ά'}:
            value = 1.4 if initial_theta else 0.2
        elif s == 'ώ':
            value = 3.2
    if p in {'ข', 'หล'} and s == 'ับ':
        value = -5.5 if p == 'ข' else -3.2

    # Include characters completed by the last byte of a split UTF-8 token.
    ch = s if len(s) == 1 else ''
    if raw and 0x80 <= raw[0] < 0xC0 and len(completed) > len(before):
        ch = completed[-1]
    if liquid_character(ch):
        value = -2.5
    if len(completed) > len(before) and completed.endswith('貯'):
        value = -4.2                   # saving/accumulating character
    if s == '··' and (position == 0 or before.endswith('·')):
        value = -2.04
    return (doc, s, (tail + raw)[-24:], position + 1), value

"""Approximate a sparse, mostly local completion response.

Positive peaks occur on counted units (especially five-star/digit/precision
expressions), card compounds, and a few conventional Chinese compounds.
Code openings and a document-opening `Title:` label are separate cases.
Uncovered text is assigned zero: this does not model the diffuse background.
"""
import unicodedata
import inflect

READS = ()
_engine = inflect.engine()
NUMBERS = {_engine.number_to_words(n): n for n in range(21)}
NUMBERS.update(single=1, double=2, triple=3)
CODE_OPENINGS = {
    '#include', '#ifndef', '#define', 'import', 'using', 'use',
    'export', 'namespace', 'def', 'class', 'int', 'char',
    'function', 'const', 'var',
}


def number(text):
    if text in NUMBERS:
        return NUMBERS[text]
    if text.isascii() and text.isdigit():
        return int(text)
    if len(text) == 1:
        return unicodedata.numeric(text, None)
    return None


def completion(token, previous, position):
    word, prev = token.strip().lower(), previous.strip().lower()
    unit = word.lstrip('-')
    if position == 0:
        if word == 'package':
            return 2.05
        if word in CODE_OPENINGS:
            return 0.61
        if word in {'i', 'we', 'our', 'my', 'by'}:
            return -0.81
        if token[:1].isspace() and word in {'"', "'"}:
            return 1.45
        if word in {'{', '{"', "{'"}:
            return 0.36
    if position == 1 and previous == 'Title' and token == ':':
        return 11.51

    n = number(prev)
    if n is not None:
        if unit in {'star', 'stars'}:
            return 4.32 + 0.14 * min(n, 7) + 4.17 * (n == 5)
        if unit in {'digit', 'digits'}:
            if prev == 'single':
                return 0.75
            base = 0.87 if unit == 'digits' else 2.26
            return base + 1.60 * (n == 5)
        if unit in {'figure', 'figures'}:
            return 2.70 + 8.98 * (n == 5)
        if unit == 'decimal':
            return 5.03
        if unit in {'letter', 'letters'}:
            return 0.96
        if unit in {'finger', 'fingers'}:
            return 4.00 if n == 5 else -0.15
        if unit in {'year', 'years'}:
            base = 0.31 if word.startswith('-') or unit == 'year' else 0.0
            return base + 0.33 * (n == 5)
        if word == '-card':
            return 5.47
        # East Asian star ratings, thousands, and the traditional foot unit.
        if word == '星':
            return 9.8 if n == 5 else 3.3
        if word == '星级':
            return 6.5 if n == 5 else 3.6
        if word == '천':
            return 3.5
        if word == '千':
            return 1.0
        if word == '尺':
            return 3.0

    if (prev in {'sig', 'significant'}
            and unit in {'fig', 'figs', 'figure', 'figures'}):
        return 2.45
    if prev in {'credit', 'debit', 'green'} and word.startswith('card'):
        return {'credit': 4.25, 'debit': 0.92, 'green': 2.46}[prev]
    if prev == 'credit' and word in {'score', 'rating', 'report', 'worth'}:
        return -2.59
    if (prev in {'gold', 'golden', 'silver', 'green'}
            and unit in {'star', 'stars'}):
        return 3.24
    if prev == 'single' and unit == 'family':
        return 6.22
    if prev in {'multiple', 'multi'} and unit == 'choice':
        return 3.13

    # Fragments of five-flower pork, five lakes/thunderbolts,
    # rounding (四舍五入), and the Olympics (五輪).
    if previous == '五':
        if word == '花':
            return 12.73
        if word in {'湖', '雷', '入', '輪'}:
            return 5.39
    if word == '五星':
        return 3.18
    # Golden flowers/needles, a treasury, and gold ornaments.
    if previous == '金':
        if word in {'花', '针', '針'}:
            return 8.5
        if word in {'库', '庫', '饰品', '飾品'}:
            return 2.33
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, position = '', 0
    else:
        _, previous, position = carry
    token = prefix.token_strings[-1]
    value = completion(token, previous, position)
    return (document, token, position + 1), float(value)

programs.haiku:
"""Layer 1 MLP down-projection, component 1808: a "counted unit" spike detector.

What it does: it fires on the word right after a small count (two to nine, as a word or a
digit) when that word is a rating or a counted unit: "five stars" (the strongest), "4-star",
"three decimal places", "3-digit", "multi-family", "five-card". A rating reads strongly
after "five" or "5", moderately after "four" or "4", and weakly after the rest. "one digit"
and large numbers such as "1985 letter" stay near zero. It also fires on a few fixed
phrases ("credit card", "significant figures", "multiple choice"), on the "Title" colon that
opens a document, and on a few code words that open a document ("package", "#include").
Everything else predicts 0. Most of this component's variance is small, diffuse activity
that no short rule captures.
"""

READS = ()

SMALL_COUNTS = frozenset(
    "two three four five six seven eight nine 2 3 4 5 6 7 8 9 二 三 四 五 六 七 八 九".split()
)
RATING_WORDS = frozenset(["star", "stars", "-star", "Star", "Stars", "-Star", "星", "星级"])

# counted unit word after a small count -> predicted activation
UNIT_AFTER_COUNT = {
    "decimal": 4.0, "decimals": 2.0, "figure": 3.0, "figures": 2.0, "-figure": 3.0,
    "digit": 2.5, "digits": 1.0, "-digit": 3.0, "family": 2.0, "-family": 3.0,
    "letter": 2.0, "letters": 1.0, "-letter": 2.0, "card": 2.0, "-card": 2.0,
    "dollar": 1.0, "-dollar": 1.0, "Diamond": 6.0, "Finger": 4.0,
}

# word right after a document-opening <|endoftext|>
DOC_START = {"package": 2.0, "#": 0.5, "#include": 0.9, "import": 0.5, "using": 0.6}
CAPITAL_DOC_START = frozenset("I A B S M P Q In By H F K T D".split())


def rating_value(count):
    """Strength of a rating word after a count: five stars ~10, four ~4, fewer ~2.5."""
    if count in ("five", "Five", "5", "五"):
        return 9.5
    if count in ("four", "Four", "4", "四"):
        return 4.0
    return 2.5


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    word = strings[-1].strip()
    if len(strings) < 2:
        return None, 0.0
    before = strings[-2]
    count = before.strip().lower()
    if before == "<|endoftext|>":
        if word in CAPITAL_DOC_START:
            return None, -0.6
        return None, DOC_START.get(word, 0.0)
    if count in SMALL_COUNTS and word in RATING_WORDS:
        return None, rating_value(before.strip())
    if count in SMALL_COUNTS and word in UNIT_AFTER_COUNT:
        scale = 1.5 if count in ("five", "5", "五") else 1.0
        return None, scale * UNIT_AFTER_COUNT[word]
    if word in ("card", "cards", "-card") and before.strip() == "credit":
        return None, 4.0
    if word == "figures" and before.strip() == "fig":
        return None, 2.5
    if word == "fig" and before.strip() == "sig":
        return None, 2.5
    if word == "choice" and before.strip() == "multiple":
        return None, 3.5
    if word == ":" and before == "Title" and len(strings) > 2 and strings[-3] == "<|endoftext|>":
        return None, 11.5
    return None, 0.0

