"""Mostly silent except at document starts and whitespace continuations.

At starts, numerals and certain articles, question labels and comment
markers give negative pulses; quotes and escaped whitespace give positive
ones. English verbs tend to be more positive than nouns. These are coarse
approximations, not an exact dictionary of first-token responses.
The start pulse persists while the same initial token repeats. Inside
documents, a blank continuing horizontal whitespace and the x of a 0x
hexadecimal prefix give positive pulses. State resets at document boundaries.
"""
import wordnet

READS = ()


def start_value(text):
    word = text.strip()
    if word.isascii() and word.isdecimal():
        return -11.9 if word == '0' else -5.94 if word == '1' else -3.1
    if text.isspace():
        if text == '\t':
            return -5.04
        if text == '\n':
            return 3.39
        if text == '\n\n':
            return 0.87
        return -1.69 if len(text) == 1 else -0.5
    if word.lower() == 'a':
        if text == 'A':
            return -8.5
        return -6.57 if text == 'a' else -3.0
    if word.lower() == 'the':
        if word == 'The':
            return -2.7
        return 0.45 if text.startswith(' ') else -0.5
    if text in {'Q', 'Question'}:
        return -8.4 if text == 'Q' else -14.8
    if text == r'\t':
        return 15.8
    if text == r'\n':
        return 8.15
    if text in {'<|im_start|>', '<|im_end|>'}:
        return 2.4
    if text.endswith('\n'):
        return 1.2
    if text.startswith(('#', '//', '/*')):
        return -3.0
    if word in {'"', "'"}:
        return 4.2
    if word == r'\"':
        return 7.0
    if text.startswith(('("', "('", '["', '{"')):
        return 3.8
    if text.startswith('_'):
        return 1.7
    if word.isascii() and word.isalpha():
        if len(word) == 1:
            return -0.3
        if word.lower() in {'in', 'of'}:
            return -1.5 if word.lower() == 'in' else -0.74
        pos = wordnet.parts_of_speech(word.lower())
        if 'verb' in pos:
            return 2.0 if 'noun' not in pos else 1.1
        if 'adverb' in pos:
            return 1.3
        return 0.4
    return 0.0


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    token = prefix.token_ids[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, initial_token, initial_run = '', token, True
    else:
        _, previous, initial_token, initial_run = carry
        initial_run = initial_run and token == initial_token

    value = start_value(text) if initial_run else 0.0
    if not initial_run:
        if previous.isspace() and '\n' not in previous:
            if text == ' ':
                value = 1.0 if previous == ' ' else 1.4
            elif text == '\t':
                value = 0.2 if previous == '\t' else 0.4
            elif text == '\u00a0':
                value = 0.6
        elif previous == '0' and text.startswith('x'):
            if all(c in '0123456789abcdefABCDEF' for c in text[1:]):
                value = 1.5
    return (doc, text, initial_token, initial_run), value

