    # Seeing-related Han characters and a Greek spelling fragment.
    if s in ('视', '視'):
        v -= 1.76
    if s == '图' and tail.endswith(('视', '視')):
        v -= 1.78
    if contiguous and old.endswith(('ει', 'οι', 'ε', 'ι')) and low.startswith('δ'):
        v -= 2.25
    return v


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, tail = ('', '') if first else carry[1:]
    s = prefix.token_strings[-1]
    value = response(s, previous, tail, first)
    match = re.search(r'[^\W\d_]+$', tail + s)
    tail = match[0][-24:] if match else ''
    return (doc, s, tail), float(value)

programs.haiku:
"""Layer 1, MLP down-projection, component 1812: a document-opening word detector.

What it does, in plain terms
- The component is essentially silent except on the first token of a document (the first
  token of a row, or the first token after a document break). There it is large, and set
  by which word opens the document; the value depends only on that word.
- High for words that open a noun phrase and expect a noun next: determiners,
  possessives, quantifiers and adjectives ("our", "their", "various", "new", "best",
  "classical"), chat/markup special tokens, and words in non-Latin scripts.
- Low for words that are usually followed by a verb, preposition or "of"/"to": sentence
  starters and pronouns written with no leading space ("The", "I", "He", "We", "There"),
  plural nouns and third-person verbs ("hands", "belongs", "rounds"), and punctuation or
  digits.
- Every other position predicts 0.
"""

READS = ()

# Words that open a noun phrase: determiners, possessives, quantifiers, common modifiers.
NP_OPENERS = {
    "our", "your", "their", "its", "my", "his", "these", "various", "several", "many",
    "multiple", "other", "new", "best", "main", "final", "multi", "non", "major", "large",
    "small", "high", "good", "great", "own", "same", "more", "most", "some", "each", "every",
    "all", "the", "a", "an", "this", "that", "such", "different", "additional", "key", "no",
}
# Pronouns and sentence-opening function words: low when written with no leading space.
SENTENCE_STARTERS = {
    "The", "A", "An", "I", "He", "She", "We", "You", "They", "There", "It", "At", "Let",
    "Here", "Where", "Who", "If", "When", "Her", "Welcome", "Men", "May", "Points",
}
ADJ_ENDINGS = ("al", "ic", "ive", "ous", "ble", "ful", "less", "ary", "ory")


def _value(token):
    """Activation predicted for a word that opens a document, as a string token."""
    space = token[:1] == " "
    word = token.lstrip(" ")
    if token.startswith("<|"):
        return 7.0  # chat and markup special tokens
    if not word:
        return 0.0
    first = word[0]
    if not first.isascii() and first.isalpha():
        return 7.5  # non-Latin word: CJK, Cyrillic, Hangul, Arabic, kana
    if first.isdigit():
        return -0.7
    if not word.isalpha():
        return 0.5 if space else 0.0  # punctuation and code symbols
    if not space and word in SENTENCE_STARTERS:
        return -1.0
    if word.lower() in NP_OPENERS:
        return 7.0
    if word[0].isupper() and not space:
        return 2.5  # capitalised word with no leading space: names, sentence starts
    if word.endswith(ADJ_ENDINGS):
        return 8.0
    if word.endswith("s") and not word.endswith("ss"):
        return 1.2  # plural noun or third-person verb
    if word.endswith("ed"):
        return 2.5
    if word.endswith("ing"):
        return 4.8
    if word.endswith("ly"):
        return 5.5
    return 3.5


def step(carry, prefix, upstream):
    """Activation at the newest token: its word's value if it opens a document, else 0."""
    t = prefix.position
    opens = t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]
    if not opens:
        return carry, 0.0
    return carry, float(_value(prefix.token_strings[t]))

programs.sol:
"""A sparse approximation from code and documentation syntax.

Strong positive writes mark Sphinx cross-references and directives, and
an initial Title colon. Smaller writes mark declarations, printing,
Python try/decorator syntax, test names, and grep after a shell pipe.
Python exits, type names and filesystem operations write negatively.
Most text is zero. This is a lexical approximation, not a full parser;
it misses many context-specific responses to ordinary identifiers.
"""
import re

READS = ()
SPHINX_ROLES = set('class func meth mod obj attr exc data const ref doc'.split())
PRINT_CALLS = {
    '.println', '.Println', '.printf', '.Printf', '.WriteLine',
    'printf', 'println', 'cout',
}
FILESYSTEM_OPERATIONS = {
    '.mkdir', '.makedirs', '.listdir', '.rmdir', '.unlink', '.remove',
}
PYTHON_TYPES = {'str', 'int', 'float', 'dict', 'set', 'list', 'tuple', 'bool'}
ROLE = re.compile(r'(?:^|[\s(`]):(?:[a-z]+:)?([a-z]+)$')
PYTHON_CUE = re.compile(
    r'\bdef\s+\w+|except\s+\w+|__name__|from\s+[\w.]+\s+import'
)
PYTHON_BLOCK = re.compile(
    r'(?:^|\n|\\n)\s*(?:\d+\s+)?'
    r'(?:if|elif|for|while|with|try|except|else|finally)\b'
    r'[^\n]{0,120}:\s*(?:\n|\\n)\s*$'
)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != document
    _, tail, python = (document, '', False) if first else carry
    s = token.strip()
    # Recognize both actual newlines and escaped newlines in tool commands.
    line = re.split(r'\n|\\n', tail)[-1]
    leading = token[:len(token) - len(token.lstrip())]
    line_start = not line.strip() or bool(
        re.fullmatch(r'\s*\d+\s+', line + leading)
    )
    before = tail.rstrip()
    word = re.search(r'([A-Za-z_]+)$', line.rstrip())
    word = word[1] if word else ''
    joined = re.sub(r'^\s*\d+\s+', '', line + token).strip()
    role = ROLE.search(line + token)
    role_before = ROLE.search(line)
    value = 0.0

    if first:
        value = -0.39 if s.isascii() and s.isalpha() else -0.16
        if s.startswith('<|'):
            value = -0.064
        elif s == 'Title':
            value = 0.067
    elif tail == 'Title' and s == ':':
        value = 5.05
    # Token boundaries expose the beginning and completion of these directives.
    elif s and joined in {'.. autos', '.. autosummary', '.. autosummary::'}:
        value = {'.. autos': 5.1, '.. autosummary': 13.2,
                 '.. autosummary::': 6.3}[joined]
    elif s and joined in {':to', ':toctree', ':toctree:'}:
        value = {':to': 3.4, ':toctree': 8.6, ':toctree:': 2.3}[joined]
    elif role and role[1] in SPHINX_ROLES:
        value = 5.9
    elif (s in {':`', ':`~'} and role_before
          and role_before[1] in SPHINX_ROLES):
        value = 3.7 if s.endswith('~') else 5.7
    elif s in {'def', 'class', 'fn'}:
        if line_start or word in {'async', 'pub', 'export'}:
            value = 1.3 if token == 'class' else 0.9
            if s == 'def':
                python = True
    elif s == 'try' and line_start and python:
        value = 2.0
    elif s in {'return', 'continue', 'break', 'raise'}:
        if python and line_start:
            value = -0.35 if s == 'return' else -0.7
    elif s in PYTHON_TYPES:
        if python and not before.endswith((':', '[', ',')):
            value = -0.32
    elif s == '(set' and python:
        value = -1.3
    elif s in {'.out', '.err'} and word == 'System':
        value = 0.69
    elif s in {'.log', '.error', '.warn'} and word == 'console':
        value = 0.77
    elif s in PRINT_CALLS:
        value = 0.4
    elif s in {'print', 'fmt', 'console'}:
        value = 0.22
    elif s == 'grep':
        value = 1.25 if before.endswith('|') else 0.15
    elif s == 'disable' and re.search(r'(?:py|es)lint\s*:\s*$', tail):
        value = 3.5
    elif s == '::' and '.py' in line:
        value = 0.58
    elif s == 'main' and word in {'int', 'void', 'fn', 'func'}:
        value = 0.65
    elif s in {'Parameters', 'RETURNS'} and line_start:
        value = 0.5
    elif s == '@' and line_start and python:
        value = 0.95
    elif python and s in FILESYSTEM_OPERATIONS:
        value = -0.85

    # A coarse language cue, reset at message/fence boundaries and C-like syntax.
    recent = tail + token
    if s == 'import' and line_start:
        python = True
    if PYTHON_CUE.search(recent[-120:]) or PYTHON_BLOCK.search(recent[-200:]):
        python = True
    if s in {'package', 'namespace', 'function', 'const', 'var', 'let'}:
        if line_start:
            python = False
    if s.endswith((';', '{')) or '```' in s or s == '<|im_start|>':
        python = False
    return (document, recent[-400:], python), value

programs.haiku:
"""layers.1.mlp.down_proj:1814 as a short program.

What it does, in plain terms. This component writes into the residual stream
mostly when the text is (a) Sphinx/reStructuredText documentation markup,
(b) a Python/Rust-style definition keyword that opens a new line, or (c) a
print/log/output call. It is near zero on ordinary prose and most code tokens,
and it is negative on the first token of each document.

Rules, checked in order (each rule returns one fixed value):
  1. First token of a document (no context before it): negative, a little
     more for capitalised words.
  2. A document opening with "Title:": the colon gets a large value.
  3. Sphinx markup: a role opener ":`" (large); a field or role name right
     after a colon, as in ":param", ":rtype", ":mod:", ":func:" (large);
     "::" after a ".. directive" line (large), after a ".py" pytest path (small).
  4. "def", "class", "fn" at the start of a line open a definition (positive).
     Inline "def" or "fn" is weaker.
  5. Output calls: println, printf, cout, console, fmt, grep (moderate);
     dotted ".log" and ".out" (console.log, System.out) (moderate);
     bare "print" (weak).
  6. "raise" at the start of a line: negative.
  Everything else: 0.
"""
READS = ()

DEFINITION_WORDS = {"def", "class", "fn"}
OUTPUT_CALLS = {"println", "printf", "Println", "Printf", "cout", "console", "fmt", "grep"}
DOTTED_OUTPUT = {"log", "out"}
REST_NAMES = {"param", "rtype", "return", "returns", "raises", "func", "class",
              "mod", "meth", "attr", "py", "exc", "obj"}


def word(s):
    """A token's bare word: no leading spaces, dots, colons or underscores; lowercase."""
    return s.strip().lstrip(".:_-").lower()


def line_so_far(strs):
    """Text on the current line before the newest token."""
    buf = ""
    for s in reversed(strs[-14:-1]):
        if "\n" in s:
            return s.split("\n")[-1] + buf
        buf = s + buf
    return buf


def step(carry, prefix, upstream):
    strs = prefix.token_strings
    s = strs[-1]
    w = word(s)
    docs = prefix.document_ids

    # 1. first token of a document
    if prefix.position == 0 or docs[-1] != docs[-2]:
        first = s.strip()[:1]
        if first.isupper():
            return carry, -0.45
        if first.islower():
            return carry, -0.33
        return carry, -0.15

    # 2. a document that opens with "Title:"
    if s == ":" and strs[-2] == "Title" and (prefix.position == 1 or docs[-3] != docs[-2]):
        return carry, 5.0

    # 3. Sphinx / reStructuredText markup
    if s.startswith(":`"):
        return carry, 4.5
    if strs[-2].endswith(":") and w in REST_NAMES:
        return carry, 3.0
    line = line_so_far(strs)
    if s.startswith("::"):
        if ".." in line:  # ".. autofunction::" style directive
            return carry, 4.0
        if ".py" in line[-8:]:  # pytest node id: tests/test_x.py::test_y
            return carry, 0.6
        return carry, 0.1

    # 4. definition keywords
    at_start = line.strip() == ""
    if w in DEFINITION_WORDS and at_start:
        return carry, 1.0
    if w == "fn":
        return carry, 0.5
    if w == "def":
        return carry, 0.3

    # 5. output and logging calls
    if w in OUTPUT_CALLS:
        return carry, 0.4
    if s.startswith(".") and w in DOTTED_OUTPUT:
        return carry, 0.6
    if w == "print":
        return carry, 0.1

    # 6. raise at the start of a line
    if at_start and w == "raise":
        return carry, -0.6
    return carry, 0.0

programs.sol:
"""Sparse lexical approximation centred on 部: a part, section, or unit.

Predict a negative pulse for standalone 部, Korean 부 / 일부, Vietnamese bộ,
and selected compounds containing 部. Regional and counter compounds are
stronger than other fused words. 步/歩 (step), standalone 布 (cloth), and
妇/婦 get smaller pulses. Vietnamese club and totality contexts attenuate
bộ. Magnitudes are rounded training estimates, not a complete account of
the component's background variation. UTF-8 fragments are joined and state
resets at document boundaries.
"""
import codecs

READS = ()
DIRECTIONS = set('东西南北中東')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        decoder = codecs.getincrementaldecoder('utf-8')('replace')
        left = ''
    else:
        _, decoder, left = carry
    split = bool(decoder.getstate()[0])
    s = decoder.decode(prefix.token_bytes[-1]).strip()
    value = 0.0
    if s == '部':
        value = -6.0 if split else -3.5
    elif s.endswith('部'):
        if len(s) == 2 and s[0] in DIRECTIONS:
            value = -5.3
        elif s.endswith(('一部', '这部', '這部')):
            value = -4.0 if len(s) <= 3 else -2.8
        else:
            value = -1.7
    elif '部' in s:
        value = -0.4 if len(s) == 2 else -0.8
        if not s.endswith(('分', '份')):
            value = -0.1
    elif s in ('부', '일부'):
        value = -2.2
    elif s.lower() == 'bộ':
        value = -5.5
        if left.rstrip().endswith('lạc'):
            value = -1.1
        elif left.rstrip().endswith('toàn'):
            value = -3.3
    elif s in ('步', '歩'):
        value = -1.6
    elif s.endswith('一步'):
        value = -0.2 if s.startswith(('进', '進')) else -1.9
    elif s in ('进步', '進步', '逐步'):
        value = -0.65
    elif s == '布':
        value = -0.3
    elif s in ('妇', '婦'):
        value = -0.25
    return (doc, decoder, (left + s)[-40:]), value

"""Approximate a generic compound-head signal with local dictionary cues.

Nominal and gerund modifiers increase predictions for selected generic
nouns (system, process, method, issue, etc.). Identifier suffixes count too, with extra
responses for tests and helper objects. Familiar dictionary compounds are
adjusted separately. Chinese heads and modifiers are recognized through
CC-CEDICT's English glosses, using the same noun concepts. This is a local,
dictionary-based approximation, not a grammatical parser. Other token
classes receive zero; most native activation variation remains unexplained.
"""
import functools
import re
import regex
import wordnet
import cedict

READS = ()

# Generic head nouns in four rough strength bands; the last is helper roles.
HEADS = (
    (0.48, (
        'service program project logic formula calculation computation '
        'industry business sector trade'
    )),
    (0.3, (
        'process procedure system framework method technique strategy '
        'approach algorithm mechanism protocol tool apparatus equipment '
        'device app software technology problem issue case question '
        'phenomenon situation rule policy law act regulation standard test '
        'experiment'
    )),
    (0.14, (
        'analysis assessment evaluation investigation function command option '
        'parameter argument configuration instruction request response '
        'message signal error warning exception event operation activity '
        'action practice behavior report page website form dialog '
        'functionality capability ability capacity feature work job task '
        'construction development production management concept principle '
        'theory idea ceremony ritual meeting conference forum exhibition '
        'condition requirement measure aspect circumstance need demand '
        'quantity proportion'
    )),
    (0.03, (
        'helper utility builder controller listener repository implementation'
    )),
)
GROUPS = tuple(set(words.split()) for _, words in HEADS)
HELPER_GROUP = 3
ALIASES = {"impl": "implementation", "utils": "utility",
           "util": "utility", "config": "configuration"}
STOP = set((
    "a an the this that these those my your his her its our their "
    "some any every each no another other such which what whose all both "
    "either neither of in on at for to from by with as is are was were "
    "be been being have has had do does did will would shall should can "
    "could may might must not and or but than then if it he she they we you i "
    "make made get got take took give gave keep kept put let see seen say said "
    "know think tell told need want go went come came become became use used "
    "find found seem look try help"
).split())

@functools.lru_cache(maxsize=65536)
def english_heads(word):
    word = ALIASES.get(word.lower(), word.lower())
    bases = set(wordnet.base_forms(word, "noun")) | {word}
    return tuple(i for i, group in enumerate(GROUPS) if bases & group)

@functools.lru_cache(maxsize=65536)
def translations(text):
    glosses = cedict.glosses(text)
    if not glosses:
        # A token can include a modifier before its dictionary head.
        for length in (4, 3, 2):
            if len(text) > length:
                glosses = cedict.glosses(text[-length:])
                if glosses:
                    break
    words = []
    for gloss in glosses:
        if gloss.startswith(("CL:", "surname ", "old variant ", "variant of ")):
            continue
        for part in re.split("[;,]", gloss):
            part = re.sub(r"\([^)]*\)", "", part).strip().lower()
            part = re.sub(r"^(a |an |the )", "", part)
            if " " not in part:
                words.append(part)
    return tuple(words)

@functools.lru_cache(maxsize=65536)
def nominal(word):
    if regex.fullmatch(r"\p{Script=Han}+", word):
        senses = [wordnet.parts_of_speech(w) for w in translations(word)]
    elif word.lower() in STOP:
        return False, False
    else:
        senses = [wordnet.parts_of_speech(word)]
    return (any("noun" in p for p in senses),
            any("noun" in p and "adjective" not in p for p in senses))

@functools.lru_cache(maxsize=65536)
def chinese_heads(word):
    word = word.removeprefix("的").removeprefix("等")
    return tuple(sorted({i for gloss in translations(word)
                         for i in english_heads(gloss)}))

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        tail, last = "", ""
    else:
        _, tail, last = carry
    word = token.strip(" _.")
    han = bool(regex.fullmatch(r"\p{Script=Han}+", word))
    if han:
        heads = chinese_heads(word)
    elif word.isascii() and word.isalpha():
        heads = english_heads(word)
    else:
        heads = ()
    value = 0.0
    if heads:
        if han:
            noun, noun_not_adjective = nominal(last)
            gerund = code = abbreviation = familiar = False
        else:
            match = re.search(r"[A-Za-z]+$", tail)
            previous = match[0] if match else ""
            noun, noun_not_adjective = nominal(previous)
            gerund = previous.lower().endswith("ing") and len(previous) > 4
            code = (not token.startswith(" ") and bool(tail)
                    and (token.startswith(("_", ".")) or word[0].isupper()))
            abbreviation = previous.isupper() and len(previous) > 1
            familiar = bool(previous) and bool(wordnet.parts_of_speech(
                previous.lower() + " " + word.lower()))
        gain = (0.2 + 0.05 * noun + noun_not_adjective + gerund
                + 0.4 * code + 0.5 * abbreviation - 0.35 * familiar)
        if han:
            gain += -0.15 + 0.85 * word.startswith("的")
        value = sum(HEADS[i][0] for i in heads) * gain
        if code:
            # Testing and helper-role names are strong identifier endings.
            bases = wordnet.base_forms(word, "noun")
            value += 0.5 * bool(set(bases) & {"test", "experiment"})
            value += 0.25 * (HELPER_GROUP in heads)
    return (doc, (tail + token)[-100:], token.strip()), float(value)

"""A positive document-opening pulse, with negative endings and conclusions.

Opening strength is estimated from simple token classes: indentation, digits,
isolated letters, selected declaration/type keywords, and decorative marks.
The pulse persists through an opening run of identical tokens. Otherwise,
return zero except for end-of-text and consequence words. Capitalized
connectives are more negative; lowercase 'so' distinguishes punctuation-led
consequences from 'if so' and 'do so'. Token-specific variation is omitted.
"""
READS = ()
CONSEQUENCES = {'so', 'thus', 'therefore', 'hence', 'consequently'}
DECLARATIONS = {'package', 'import', 'from', 'using', 'def', 'class', 'export'}
TYPES = {'int', 'string', 'char', 'float', 'double', 'bool', 'void'}


def start_value(token):
    s = token.strip()
    if token == '<|im_start|>':
        return 2.84
    if token == '<|endoftext|>':
        return 12.3
    if token == s and s in DECLARATIONS:
        return 10.5
    if token == s and s in TYPES:
        return 11.0
    if not s:
        if '\t' in token:
            return 9.0
        return 7.0 if len(token) > 1 and token.strip(' ') == '' else 4.0
    if s.isdigit():
        return 3.8
    if len(s) > 1 and len(set(s)) == 1 and s[0] in '#*^·':
        return 9.0
    if len(s) == 1 and s.isascii() and s.isalpha() and token == s:
        return 2.0
    return 3.1


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        opening, repeating = token, True
    else:
        _, opening, repeating = carry
        repeating = repeating and token == opening
    value = 0.0
    if repeating:
        value = start_value(token)
    elif token == '<|endoftext|>':
        value = -0.89
    elif token.strip().lower() in CONSEQUENCES:
        word = token.strip()
        if word.lower() == 'consequently':
            value = -0.32 if word[0].isupper() else -0.19
        elif word.lower() == 'so' and word.islower():
            previous = prefix.token_strings[-2].strip().lower()
            if previous == 'if':
                value = 0.25
            elif previous in {'do', 'does', 'did', 'doing', 'done'}:
                value = 0.05
            elif previous.endswith((',', '.', ':', ';', '!', '?', ')')):
                value = -0.59
            else:
                value = -0.29
        else:
            value = -0.9 if word[0].isupper() else -0.47
    return (doc, opening, repeating), value

"""Expectations and specified program behavior, plus a few opening formats.

'Should' and check marks get positive responses.  'Should' and 'must'
get stronger near programming terms or comment/header markers; 'should'
gets weaker after personal pronouns.  Clauses and verbs describing
program behavior get smaller positive responses.  Separate rules handle
initial code declarations, Title: / <?php openings, and middle-dot dividers.
The short context is a 100-character suffix, with literal \\n interpreted
as a line break.  This leaves finer contextual variation unexplained.
"""
import re

READS = ()
TECHNICAL_NOUNS = {
    'function', 'method', 'program', 'algorithm', 'class', 'object', 'array',
    'output', 'input', 'value', 'test', 'script', 'variable', 'result',
    'service', 'implementation', 'code', 'routine', 'module', 'file',
    'component', 'system', 'application', 'problem', 'path',
}
TECHNICAL = re.compile(
    r'\b(' + '|'.join(TECHNICAL_NOUNS) + r')s?\b', re.I)
REQUEST = re.compile(r'\b(write|create|implement|develop|build|writing)\b', re.I)
DECLARATIONS = {
    'package', 'import', 'using', 'namespace', 'from', 'class', 'function',
    'def', 'const', 'var', 'int', 'char', 'string', 'type', 'public',
    'private', 'static', 'void',
}
BEHAVIOR_VERBS = {
    'takes', 'uses', 'prints', 'asks', 'returns', 'receives', 'prompts',
    'accepts', 'does', 'creates', 'generates', 'calculates', 'outputs',
