def step(carry, prefix, upstream):
    token, document = prefix.token_strings[-1], prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, 0, '', '', '')
    _, position, previous, recent, opening = carry
    word = token.strip().lstrip('._').lower()
    technical = bool(TECHNICAL.search(recent))
    subject = (previous in TECHNICAL_NOUNS
               or previous.rstrip('s') in TECHNICAL_NOUNS)
    line = recent.rsplit('\n', 1)[-1]
    comment = '#' in line or '//' in line
    value = -0.00138

    if position == 0:
        value -= 0.046
        if word in DECLARATIONS:
            value -= 1.124
        if token.startswith(('#', '//', '/*', '"""')):
            value -= 0.712
    if position == 1 and opening == 'Title' and token == ':':
        value += 7.129
    if position == 1 and opening == '<?' and word == 'php':
        value += 1.912
    if token and set(token) == {'·'} and len(token) > 1:
        value -= 0.712

    if '✓' in token:
        value += 0.561 + 0.276 * token.startswith(' ')
    if '✔' in token:
