    elif word in {'can', 'will', 'could', 'would', 'may', 'might'}:
        value += {'can': 0.007, 'will': -0.012, 'could': 0.023,
                  'would': 0.009, 'may': 0.010, 'might': 0.009}[word]
        if word in {'can', 'will', 'could'}:
            value += 0.020 * technical

