        requested = bool(REQUEST.search(recent))
        value += 0.024 + 0.085 * (previous == 'program')
        value += requested * (0.188 + 1.679 * (previous == 'program'))
    if word in BEHAVIOR_VERBS:
        value += 0.055
        value += 0.251 * (technical and (subject or previous in {'that', 'which'}))
    if word == 'called' and subject:
        value += 0.963
    if word in {'return', 'print', 'take', 'use', 'work', 'be'}:
        value += 0.020 * (previous in {'should', 'must', 'shall'})

