    return carry, value

programs.haiku:
"""layers.1.mlp.down_proj:1818, a sparse feature that reads "requirement" and "pass" wording.

What it does, in plain terms:
- Fires positively on the word "should" (and "Should"), the strongest and most common trigger,
  and more weakly on "must". Both mark a sentence that states what something is required to do,
  as in "The function should take N" or "the service must have ...".
- Fires positively on check marks such as ✓ and ✔ (test-output "pass" lines), and weakly on
  cross marks ✗ and ❌.
- Fires strongly positive on the colon of a document that opens with "Title:" (the first two
  tokens of a document), the largest spike in the data.
- Is pushed negative at the very start of a document when that document opens with code or
  markup (package, import, using, #, /*, //, int, class, def, function, ...), and on runs of
  dot leaders (··).
Everything else is predicted as 0. Positions are counted from each document's first token;
a document starts after each document-id change.

Why these: on held-out training rows these word classes explain most of the variance a short
rule set can capture; the rest is diffuse token-level noise that no short rule reproduces.
"""

READS = ()

SHOULD = {" should", "should", " Should", "Should"}
MUST = {" must", "must", " Must", " MUST"}
CHECK = {" ✓", "✓", " ✔", "✔", " ✅", "✅"}
CROSS = {" ✗", "✗", " ❌", "❌"}
DOT_LEADERS = {"··"}
CODE_OPENERS = {"package", "import", "using", "#", "##", "//", "/*", "int", "class", "from",
                "def", "var", "function", "#include", "#ifndef", "theorem", "{"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if carry is None:
        pos, prev = 0, None
    else:
        pos, prev = carry
        pos += 1
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        pos = 0
    carry = (pos, tok)
    if pos == 0:
        opens_code = tok in CODE_OPENERS or tok.startswith("#") or tok.startswith("/*")
        return carry, (-1.0 if opens_code else 0.0)
    if pos == 1 and prev == "Title" and tok == ":":
        return carry, 7.0
    if tok in DOT_LEADERS:
        return carry, -0.7
    if tok in SHOULD:
        return carry, 0.5
    if tok in MUST:
        return carry, 0.2
    if tok in CHECK:
        return carry, 0.7
    if tok in CROSS:
        return carry, 0.3
    return carry, 0.0

programs.sol:
"""A large negative opening-token signal, with a small code-receiver response.

Opening tokens (including an unbroken repetition of the opening token) have
usually much larger negative activations than contextualized tokens. Their
magnitude is estimated from familiar lexical and typographic properties, not
from token IDs. Indented object receivers in code instead get a positive write.
"""
import math
from functools import lru_cache
import regex
import wordfreq
import wordnet

READS = ()
ARTICLES = set('a an the'.split())
PRONOUNS = set('i me my mine we us our ours you your yours he him his '
               'she her hers it its they them their theirs'.split())
CONJUNCTIONS = set('and or but nor yet so'.split())


@lru_cache(maxsize=8192)
def opening(t):
    s = t.strip()
    if t.startswith('<|'):
        return -9.36 if t == '<|im_start|>' else -5.3
    if not s:
        if t == ' ':
            return 0.66
        if '\t' in t:
            return -10.5
        if '\n' in t or '\r' in t:
            return -3.1 if t == '\n' else -1.6
        return -4.3 - 0.85 * math.log1p(len(t))
    if '\ufffd' in s:
        return -2.5
    if s.isdecimal():
        return -1.35
    n = sum(c.isalpha() for c in s)
    if not n:
        if len(s) == 1:
            return -0.3 if not t.startswith(' ') else -1.2
        if len(set(s)) == 1 and s[0] not in '.-/#':
            return -4.5
        return -2.2
    lower = s.lower()
    if lower in ARTICLES:
        return -6.7
    if lower in PRONOUNS:
        return -6.1
    if lower in CONJUNCTIONS:
        return -5.5
    value = -3.5 - 1.4 * math.log1p(n) - 1.2 * (n >= 4)
    value += 0.4 * (n == 1) - 0.7 * s.isupper()
    value -= 1.6 * (s.istitle() and n > 1)
    value += 0.65 * t.startswith(' ') - 1.25 * (n != len(s))
    if regex.fullmatch('[A-Za-z]+', s):
        frequency = wordfreq.zipf_frequency(lower, 'en')
        value -= 0.3 + 0.14 * frequency
        value += 0.8 * (frequency < 2)
        value -= 1.6 * ('verb' in wordnet.parts_of_speech(lower))
    elif regex.search(r'\p{Script=Han}', s):
        value -= 0.6
    elif regex.search(r'\p{Script=Cyrillic}', s):
        value += 1.65
    return value


def step(carry, prefix, upstream):
    t = prefix.token_strings[-1]
    token = prefix.token_bytes[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, True, '', '')
    _, first, uniform, line, previous = carry
    uniform = uniform and token == first
    s = t.strip()
    indentation = bool(line) and not line.strip(' \t0123456789')
    code = bool(regex.search(r'(?:[=({;$]|\breturn)\s*$', line))
    value = 0.0
    if uniform:
        value = opening(t)
    elif s in {'this', 'self'}:
        if indentation or t.startswith('\t'):
            value = 1.6 if s == 'this' else 1.4
        elif code:
            value = 1.0 if s == 'this' else 0.65
    elif s == '->' and previous.strip() == 'this':
        value = 1.7
    elif s == 'or':
        value = 0.16
    elif s == '或':
        value = 0.5
    elif indentation and s in {'private', 'protected', 'public'}:
        value = 0.35
    elif indentation and s == 'constructor':
        value = 0.9
    line = (line + t.replace('\\n', '\n')).rsplit('\n', 1)[-1][-120:]
    return (doc, first, uniform, line, t), float(value)

"""Approximate a rare document-opener response, with small syntax baselines.

Empty // comment lines, HTML declarations and carriage-return-only document
starts give large positive outputs. Initial code declarations tend positive;
possessive/article openings tend negative. Initial digits have a weak
upward trend with their numerical value. Away from the start, use only a
few punctuation, indentation and code-keyword categories, not token IDs.
The many small, context-dependent activations in prose are left near zero.
"""
READS = ()

ARTICLES = frozenset({'a', 'an', 'the'})
PREPOSITIONS = frozenset(
    'of to in for on at by with into over under between after before '
    'through without about as'.split()
)
POSSESSIVES = frozenset({'my', 'our', 'your', 'their'})
IMPORTS = frozenset({'import', 'from', 'package'})
DEFINITIONS = frozenset({'class', 'def', 'function'})
DECLARATIONS = frozenset({'const', 'class', 'def', 'void', 'fn'})
ACTIONS = frozenset({
    'Add', 'Create', 'Delete', 'Find', 'Get', 'Give', 'Install',
    'Choose', 'Read', 'Remove', 'Replace', 'Search', 'Select',
    'Set', 'Update', 'Write', 'Download',
})


def ordinary(token):
    x = token.strip()
    if '\u00a0' in token and not x:
        return -0.07
    if token.isspace():
        if '\t' in token and ' ' in token:
            return -0.07 if len(token) >= 8 else 0.05
        return 0.0
    if x == '://':
        return 0.16
    if x in {'\\n', '\\r', '\\t'}:
        return 0.04
    if '\\' in x and '"' in x:
        return -0.07
    if x in {"'", "'s", "'ve", "'re", "'ll", "'d", "n't", "'m"}:
        return -0.035
    if x in {'/', '\\', '>', '|', '+'}:
        return -0.03
    if x in {'//', '/*', '*/'}:
        return -0.03
    if x == '-':
        return -0.008
    if x == '(':
        return 0.009
    if x in {'):', ']:', '}:'}:
        return 0.07
    if x in {'⇒', '→', '✓', '✔', '✅'}:
        return 0.09
    if x in DECLARATIONS:
        return -0.06
    if x == 'import' and not token.startswith(' '):
        return -0.08
    if x == 'return':
        return 0.12 if token.startswith('\t') else 0.04
    return 0.0


def initial(token):
    x = token.strip()
    if token == '//\n':
        return 4.58
    if token == '<!':
        return 3.96
    if token == '<?':
        return 0.51
    if token == '\r\n':
        return 0.63
    if token == '\t':
        return -0.71
    if token == '\n':
        return -0.21
    if x and set(x) == {'#'} and len(x) > 1:
        return -0.4
    if token == '/*\n':
        return -0.32
    if token and set(token) == {' '}:
        return min(0.4, 0.12 * (len(token) - 1))
    if x in IMPORTS:
        return 0.35
    if token in DEFINITIONS:
        return 0.75
    if x.lower() in POSSESSIVES:
        return -0.55
    if x.lower() in ARTICLES:
        return -0.2
    if token.startswith(' ') and x in PREPOSITIONS:
        return -0.18
    if x in ACTIONS:
        return 0.35
    if len(x) == 1 and x in '0123456789':
        return -0.32 + 0.065 * int(x)
    if x in {'"', "'", '('}:
