    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    only_returns = first or carry[1]
    if token == '\r':
        value = 3.64 if only_returns else 0.125
    else:
        value = initial(token) if first else ordinary(token)
    return (doc, only_returns and token == '\r'), value

"""Approximate phonetic joins, not a general language detector.

A completed pinyin syllable followed by another consonant can give a
positive response. Vietnamese vowel completions and the Thai cancellation
mark give negative responses. Most positions are quiet. Document-initial
tokens have their own coarse spelling baselines.
