import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency
from pypinyin.constants import PINYIN_DICT
from pypinyin.contrib.tone_convert import to_normal

READS = ()
# Mandarin dorsal (velar/palatal) and retroflex consonant initials.
BACK_ONSETS = set('g k h j q x zh ch sh r'.split())
SYLLABLES = {to_normal(r) for readings in PINYIN_DICT.values()
             for r in readings.split(',')}
SYLLABLES = {s for s in SYLLABLES if any(v in s for v in 'aeiouv')}


def letters(s):
    return bool(s) and s.isascii() and s.isalpha()


@lru_cache(30000)
def english(s):
    return zipf_frequency(s, 'en')


@lru_cache(30000)
def pinyin_word(s):
    """Whether the letters split into complete Mandarin syllables."""
    s = s.lower()
    if not letters(s) or len(s) > 20:
        return False
    ends = {0}
    for end in range(1, len(s) + 1):
        if any(start in ends and s[start:end] in SYLLABLES
               for start in range(max(0, end - 6), end)):
            ends.add(end)
    return len(s) in ends


def response(first, s, previous, word):
    t = s.strip()
    if first:
        if s == '\t':
            return 1.34
        if s[:1].isspace():
            return 0.06
        if letters(t):
            return -0.27
        return -0.33 if t.isdigit() else -0.075
    if s == '์':                 # Thai consonant-cancellation mark.
        return -0.2
    low = t.lower()
    before = unicodedata.normalize('NFD', previous[-1:].lower())
    now = unicodedata.normalize('NFD', low)
    if not s[:1].isspace():
        # Vietnamese iê/yê vowel sequences, split before the accented e.
