            return 0.6
        if (low in SYLLABLES and low[:1] not in 'aeiou'
                and english(t) <= 4.5):
            return 0.35
    if (s[:1].isspace() and len(t) == 1 and t.isupper()
            and prev.istitle() and len(prev) > 1 and english(prev) <= 4.5):
        return 0.28
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, word = ('', '') if first else carry[1:]
    s = prefix.token_strings[-1]
    value = response(first, s, previous, word)
    if letters(word + s):
        word = (word + s)[-20:]
    else:
        match = re.search('[a-zA-Z]+$', s)
        word = match.group() if match else ''
    return (doc, s, word), value

"""A pulse at the first model-visible token of a document.

Training examples concentrate large responses at context resets.
Keep the pulse through an initial run of identical tokens, then go quiet.
Estimate its size from typography and closed grammatical word classes;
these are class averages, not an exact lexical lookup. Newlines and caret
runs are positive; most other classes are negative. Also recognize the
large negative response on the colon of an opening 'Title:' field.
