import unicodedata

READS = ()

# Closed grammatical classes, not a vocabulary of fitted token identities.
QUESTION = set("who what when where why how which whom whose".split())
NEGATION = set("no not never none neither nor".split())
POSSESSIVE = set("my our your his her its their mine ours yours hers theirs".split())
PREPOSITION = set(
    "in on at of to for from with without by as into over under between "
    "through before after".split()
)


def pulse(s):
    t = s.strip()
    if not t:
        if '\n' in s:
            return 1.8
        return 0.0 if '\t' in s else -1.6
    if t == '<|endoftext|>':
        return 3.6
    if t.startswith('<|'):
        return -4.8
    if t.isdecimal():
        return -3.2 + 0.3 * int(t) if len(t) == 1 else -2.3
    if '\ufffd' in t:
        return -1.2
    if set(t) == {'·'}:  # Middle-dot leaders.
        return -11.0
    if set(t) == {'^'}:  # Caret runs.
        return 7.3
    if not any(c.isalpha() for c in t):
        return 2.3 if '\n' in s else -2.3
    if t.isascii() and t.isalpha():
