            return -6.3
        if lower == 'the':
            return -3.8 if capital else -3.3
        if lower in NEGATION:
            return -14.0 if capital else -11.0
        if lower in QUESTION:
            return -7.6 if capital else -4.7
        if lower in POSSESSIVE:
            return -4.0 if capital else 0.4
        if lower in PREPOSITION:
            return -6.6 if capital else -3.3
