start of a document: a // comment header, or an initial run of CRs.
Spaced English let/Let has a small positive response.
"""
READS = ()
LET_BYTES = "让".encode("utf-8")


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    if first:
        previous, only_cr = b'', True
