        if len(text) == 1:
            value = -9.9 if text == '讓' else -7.3
            if previous_text.endswith(('能', '会', '會')):
                value = -6.1
        elif '让人' in text or '讓人' in text:
            value = -4.2
        else:
            value = -5.8
    elif raw == LET_BYTES[-1:] and previous.endswith(LET_BYTES[:-1]):
        value = -10.8
    elif text == '\r':
        value = 5.65 if only_cr else 0.1
    elif first and text == '//\n':
        value = 8.35
    elif text in (' let', ' Let'):
        value = 0.25
    else:
        value = 0.0
    return (document, raw, only_cr and text == '\r'), value

