"""Layer-1 MLP down-projection component 1828: an operator detector.

The component is silent on most text. It speaks on the operators of maths and
code, '=', '+' and '-', on the first number after a bare '=', and on the LaTeX
openers sqrt and frac. Its value depends on the operator, on whether a space comes
before it ("x = 1" vs "x=1"), and on what stands just before it:

  * '=' right after a single-letter variable is negative, and more so when a
    lead-in word ("for", "at", "when", "let", ...) starts the clause: a variable
    being given a value ("for n=0", "at t = 1");
  * '=' or '+' after a closing bracket, superscript or line start is positive: an
    equation or sum over a compound expression ("f(x) = ", "x² + ", a line that
    starts with "=");
  * '+' and '-' after a space and a word, number or bracket are mildly positive;
  * a digit straight after '=' is mildly negative (the value being assigned);
  * sqrt and frac are mildly positive.

The numbers are mean activations per case, fitted on training text; every other
token gets 0. Across 1024 eval rows this explains about 20% of the variance.
"""
READS = ()

CLOSE = (")", "]", "}", "²", "³")
LEAD_IN = {"for", "at", "when", "if", "let", "with", "where", "then", "so", "to", "from", "and", "is"}

# (operator, space before it, what precedes it) -> mean activation
TABLE = {
    ("=", False, "VAR"): -1.8, ("=", False, "OTH"): -0.6, ("=", False, "DIG"): -0.2,
    ("=", False, "CLOSE"): 1.5, ("=", False, "NL"): 2.4,
    ("=", True, "VAR"): -0.3, ("=", True, "OTH"): 0.1, ("=", True, "DIG"): 0.5,
    ("=", True, "CLOSE"): 1.2,
    ("+", False, "CLOSE"): 0.4, ("+", False, "VAR"): -0.1,
    ("+", True, "VAR"): 0.8, ("+", True, "OTH"): 0.4, ("+", True, "DIG"): 0.8,
    ("+", True, "CLOSE"): 1.4,
    ("-", True, "VAR"): 0.4, ("-", True, "OTH"): 0.2, ("-", True, "DIG"): 0.5,
    ("-", True, "CLOSE"): 1.0,
}
# a variable with a lead-in word before it: "for n=", "at t ="
LEAD_TABLE = {("=", False): -3.1, ("=", True): -1.6}


def _kind(prev):
    s = prev.strip()
    if 1 <= len(s) <= 2 and s.isalpha():
        return "VAR"
    if s.endswith(CLOSE):
        return "CLOSE"
    if s.isdigit():
        return "DIG"
    if prev == "" or "\n" in prev:
        return "NL"
    return "OTH"


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if len(toks) < 2:
        return None, 0.0
    cur, prev = toks[-1], toks[-2]
    op = cur.strip()
    if op.isdigit() and prev.strip() == "=":
        return None, -0.6
    if op in ("sqrt", "frac"):
        return None, 1.1
    if op not in ("=", "+", "-"):
        return None, 0.0
    spaced = cur.startswith(" ")
    kind = _kind(prev)
    if kind == "VAR" and any(t.strip() in LEAD_IN for t in toks[-5:-2]):
        return None, LEAD_TABLE.get((op, spaced), 0.0)
    return None, TABLE.get((op, spaced, kind), 0.0)

programs.sol:
"""Mostly an English progressive-aspect detector: 'is/was ... doing'.

Join word pieces, recognize forms of 'be' (including contractions), and allow
adverbs, negation and inverted questions before the -ing verb. Infinitival 'be'
is weaker. A negative response extends to connectors, especially prospective
'going to', 'starting to', and 'about to'. Selected other complements give
small positive responses. Spanish/Portuguese estar + gerund is similar.
Separate positive cues are public GitHub hostnames and opening Title: headers.
There is also a small positive document-initial bias.
These rules approximate the syntax, not each verb's individual strength.
"""
import re
import unicodedata
from functools import lru_cache
import wordnet

READS = ()
WORD = re.compile(r'[^\W\d_]+$')
EXISTENTIAL = re.compile(r"\bthere(?:'s|\s+(?:is|are|was|were))"
                         r"(?:\s+[a-z]+){0,4}\s*$")
AUX = re.compile(r"\b(am|is|are|was|were|been|be)\b|'(m|re|s)\b")
BRIDGES = set('not never always still just now already also really even '
              'currently actually probably certainly usually often only '
              'ever yet no longer indeed all both each almost maybe soon '
              'today you we they he she it i this that these those'.split())
PRONOUNS = set('it he she that there what who how where when why'.split())
EVALUATIVE = set('interesting exciting boring amazing surprising confusing '
                 'frustrating disappointing satisfying encouraging alarming '
                 'worrying shocking tiring exhausting challenging fascinating intriguing '
                 'disgusting charming overbearing stunning overwhelming willing '
                 'wanting demanding'.split())
PREPOSITIONS = set('to of at with for about on in from into out'.split())
ESTAR = set('estoy estas esta estamos estais estan estaba estaban estabamos '
            'estou estao estava estavas estavamos estavam esteve'.split())

@lru_cache(maxsize=8192)
def ing_verb(word):
    if not word.endswith('ing') or word.endswith('thing'):
        return False
    forms = wordnet.base_forms(word)
    return any(b != word for b in forms) or (not forms and len(word) > 6)


def context(before):
    before = before.replace("n't", ' not')
    matches = list(AUX.finditer(before))
    if not matches:
        return '', 0
    m = matches[-1]
    tail = before[m.end():]
    if not re.fullmatch(r'(?:\s+[a-z]+){0,4}\s*', tail):
        return '', 0
    aux = m[1] or {'m': 'am', 're': 'are', 's': 'is'}[m[2]]
    lead = before[:m.start()].rstrip()
    if m[2] == 's':  # possessive 's is not usually an auxiliary
        subject = WORD.search(lead)
        if not subject or subject[0] not in PRONOUNS:
            aux = 'ambiguous_s'
    gap = tail.split()
    modifiers = all(w in BRIDGES or w.endswith('ly') for w in gap)
    question = re.search(r'\b(why|how|what|where|when)$', lead)
    if modifiers or (question and len(gap) <= 4) or gap == ['up', 'and']:
        return aux, len(gap)
    return '', 0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', 0.0, '', 0)
    _, history, previous_pulse, previous_word, position = carry
    token = prefix.token_strings[-1].lower().replace('’', "'")
    raw = (history + prefix.token_bytes[-1])[-512:]
    text = raw.decode('utf-8', errors='replace').lower().replace('’', "'")[-160:]
    text = text.replace('\\n', ' ').replace('\\t', ' ').replace("\\'", "'")
    match = WORD.search(text)
    word = match[0] if match else ''
    before = text[:match.start()] if match else ''
    aux, gap = context(before)
    value = 0.2 if position == 0 else -0.001
    pulse = 0.0
    if aux and ing_verb(word):
        magnitude = 2.8 if aux in {'is', 'are', 'am'} else 2.35
        if aux == 'be':
            magnitude = 1.3
        elif aux == 'ambiguous_s':
            magnitude = 0.6
        if word == 'going':
            magnitude += 0.65  # frequent prospective 'be going to'
        if EXISTENTIAL.search(before) and word not in {'being', 'going'}:
            magnitude *= 0.12  # 'there are charming pictures' is not progressive
        if word in EVALUATIVE:
            magnitude *= 0.16  # normally an adjective, not an ongoing action
        pulse = -magnitude * (0.93 ** gap)
        value += pulse
    elif aux and aux != 'ambiguous_s':
        if word in {'ready', 'supposed', 'encouraged', 'reminded'}:
            value += 0.65 if aux in {'am', 'is', 'are'} else 0.1
        elif word in {'my', 'our', 'your', 'his', 'her', 'their'}:
            value += 0.4 if aux != 'be' else 0.06
        elif word.endswith('ed'):
            value += 0.55 if aux == 'am' else -0.06 if aux == 'be' else 0.1
        elif word in {'now', 'currently'} and aux not in {'be', 'been'}:
            value -= 1.0 if word == 'now' else 0.65
    if previous_pulse and token.startswith(' '):
        factor = 0.0
        if word in PREPOSITIONS:
            factor = 0.32
        elif word in {'a', 'an', 'this'}:
            factor = 0.23
        elif word in {'the', 'these', 'those'}:
            factor = 0.07
        elif previous_word == 'being':
            factor = 0.15
        value += factor * previous_pulse
        if word == 'to':
            if previous_word == 'going':
                value = -1.9
            elif previous_word in {'starting', 'beginning'}:
                value = -3.4
    # Other aspectual phrases: imminent action and action in progress.
    if word == 'to' and before.endswith('about '):
        if context(before[:-6])[0]:
            value = -2.7
    if word == 'of':
        phrase = re.search(r'in the (process|midst|middle)\s+$', before)
        if phrase and context(before[:phrase.start()])[0]:
            value = -2.7
    # Spanish and Portuguese progressive forms, with accents folded locally.
    if word.endswith(('ando', 'iendo', 'endo', 'indo')):
        words = ''.join(c for c in unicodedata.normalize('NFD', before)
                        if not unicodedata.combining(c)).split()
        if any(w in ESTAR for w in words[-3:]):
            value = -2.7
    github_host = re.search(
        r'(?<![\w.])(?:github|(?:raw\.)?githubusercontent)\.com$', text)
    if token.endswith('.com') and github_host:
        value = 2.7
    if position <= 1 and text.strip() == 'title:':
        value = 5.72
    return (doc, raw, pulse, word, position + 1), float(value)

programs.haiku:
"""Ongoing-action detector for layers.1.mlp.down_proj:1829.

What it does: this component goes negative on the -ing verb of an ongoing action
that follows a form of "be", with at most two adverbs or negations in between
("is going", "are using", "was happening", "am thinking", "aren't getting",
"is now being"). It is most negative on "going" ("is going to", "is going on"),
and weaker for verbs of thinking or feeling and for -ing words that are really
adjectives ("is exciting" stays near 0). The word right after such a verb is also
negative when it is a preposition ("going to", "working on", "talking about",
"looking at") and weakly for an article or "for/with/in" ("looking for a").
Separately, "to" after "trying", "starting", "beginning" is negative, "now" or
"currently" after "is/are" is negative, and "com" in "github.com" is positive.
Everywhere else it predicts 0.
"""

READS = ()

BE_FORMS = {
    "is", "are", "was", "were", "am", "be", "been", "being",
    "'s", "'re", "'m", "’s", "’re", "’m", "aren", "isn", "wasn", "weren",
}
ADVERBS = {
    "not", "now", "also", "still", "currently", "presently", "really", "just",
    "always", "only", "never", "'t", "n't", "n’t",
}
# -ing words that are not progressive verbs
NOT_PROGRESSIVE = {
    "something", "nothing", "everything", "anything", "thing", "during", "string",
    "including", "according", "following", "morning", "evening", "meaning",
}
# -ing words that are usually adjectives ("is exciting"): near 0
ADJECTIVE_ING = {
    "exciting", "interesting", "amazing", "frustrating", "challenging", "confusing",
    "disturbing", "surprising", "willing", "refreshing", "stunning", "encouraging",
    "boring", "shocking", "fascinating", "pleasing", "forthcoming", "existing",
}
# verbs of thinking, waiting and feeling: weaker than action verbs
MENTAL_ING = {
    "thinking", "waiting", "hoping", "expecting", "finding", "missing", "choosing",
    "understanding", "wanting", "feeling", "believing", "knowing", "wondering", "living",
}
STRONG_AFTER = {"to", "on", "about", "at", "of"}
WEAK_AFTER = {"a", "an", "for", "with", "in"}
ASPECT_VERBS = {"trying", "starting", "beginning", "tried", "started", "began"}


def _word(s):
    return s.strip().lower()


def _is_ing(s):
    w = _word(s)
    return s.startswith(" ") and w.isalpha() and w.endswith("ing") and w not in NOT_PROGRESSIVE


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    docs = prefix.document_ids
    t = len(strings) - 1
    cur = _word(strings[t])

    def prev(k):
        # the word k tokens before the current one, if it is in the same document
        i = t - k
        if i < 0 or docs[i] != docs[t]:
            return None
        return _word(strings[i])

    def is_progressive_verb_at(k):
        # is the token k back an -ing verb after a form of "be", with up to two
        # adverbs or negations in between?
        s = prev(k) if k > 0 else cur
        if s is None or not _is_ing(strings[t - k]):
            return False
        j = k + 1
        while prev(j) in ADVERBS or (prev(j) or "").endswith("ly"):
            j += 1
            if j - k > 2:
                return False
        return prev(j) in BE_FORMS

    value = 0.0
    if _is_ing(strings[t]):
        if is_progressive_verb_at(0):
            if cur in ADJECTIVE_ING:
                value = 0.0
            elif cur in MENTAL_ING:
                value = -1.3
            elif cur == "going":
                value = -3.5
            else:
                value = -2.4
    elif is_progressive_verb_at(1):
        if cur in STRONG_AFTER:
            value = -1.6
        elif cur in WEAK_AFTER:
            value = -0.6
    elif cur == "to" and (prev(1) in ASPECT_VERBS or prev(1) == "going"):
        value = -1.5
    elif cur in {"now", "currently", "presently"} and prev(1) in BE_FORMS:
        value = -1.0
    elif cur == ".com" and prev(1) in {"github", "ithub"}:
        value = 2.5
    return carry, value

programs.sol:
"""Negative pulses mark numbered lists and section-label punctuation.

Item 1, Markdown headings, and the beginning of a document receive stronger
pulses. Title fields (including issue-title markup), lesson plans and
writing/essay prompts supply further negative cues. Forum membership labels
(Joined, Join Date, Posts) are positive. Small baseline predictions cover
the document's first token and ellipses. State resets for each document.
These are coarse empirical pulses, not predictions of background variation.
"""
import re

READS = ()
NUMBER = re.compile(r'([ \t#>*]*)(\d+)$')
TITLE = re.compile(r'(?:\d+\.\s*)?(?:book\s+)?title$')
HEADING = re.compile(
    r'.*\b(?:step|test|chapter|section|part|example|question|exercise|'
    r'episode|slide|lesson|method)\s+\d+$', re.I,
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        line, previous, age = '', '', 0
    else:
        _, line, previous, age = carry
    token = prefix.token_strings[-1]
    word, prev = token.strip().lower(), previous.strip().lower()
    value = 0.0
    ordinal = NUMBER.fullmatch(line)
    title = line.strip(' \t*#|').lower()
    if token == '.' and ordinal:
        number = ordinal[2]
        value = (-1.25 if number == '1' else
                 -0.55 if len(number) == 1 else -0.35)
        if '#' in ordinal[1]:
            value -= 1.0
        if age <= len(number):
            value = (-3.9 if number == '1' else
                     -2.7 if len(number) == 1 else -0.5)
        elif age < 16:
            value -= 1.0
        elif age < 64:
            value -= 0.5
        if number == '0':
            value = -0.15
    elif token == ':' and HEADING.fullmatch(line):
        value = -0.65
    elif token in (':', ':**') and TITLE.fullmatch(title):
        value = -4.0 if title == 'book title' else -2.2
        if age < 2:
            value = 0.0
    elif token == ':' and title in ('q', 'question', 'subject'):
        value = -0.4
    elif word == 'title' and title == 'book' and token.startswith(' '):
        value = -5.0
    elif (word in ('plan', 'plans') and prev == 'lesson'
          and token.startswith(' ')):
        value = -2.2
    elif (word in ('prompt', 'prompts', 'questions', 'topics')
          and prev in ('essay', 'writing') and token.startswith(' ')):
        value = -3.5 if word in ('prompt', 'prompts') else -2.0
    elif word == 'date' and prev == 'join':
        value = 2.1
    elif word == 'joined' and not line.strip(' •'):
        value = 3.0 if not line.strip() else 1.9
    elif token == 'Posts' and not line.strip():
        value = 0.5
    elif token == ':' and previous == 'Joined':
        value = 3.8
    elif token == ':' and previous == ' Joined':
        value = 1.1
    elif token == ':' and previous == 'Posts':
        value = 0.6
    elif token == '>Title' and line.endswith('issue_comment'):
        value = -5.7
    elif token == '1' and not line.strip(' \t#>*'):
        value = -0.3 if prev in (':', '：', '.', '。') else -0.1
    elif token.strip() in ('...', '....', '.....') and '\n' not in token:
        value = -0.25 if token.startswith(' ') else -0.15
    if first:
        value = -0.7 if token.strip().isdigit() else -0.15
    line = (line + token).rsplit('\n', 1)[-1][-256:]
    return (doc, line, token, age + 1), value

"""Predict a local comma/indefinite-article syntax response.

Ordinary commas are strong; introductory connectives, code and numbers weaken
it. English a/an is boosted after verbs and prepositions and reduced after
copulas, quantifiers, single-letter words and non-English context. Words ending
in s slightly strengthen commas. WordNet supplies grammatical classes; wordfreq
supplies a rough English-versus-other-European-language check. Smaller rules
cover non-Latin commas, German articles and newline-bearing code delimiters.
These are approximate responses, not a parser. State is only recent document
text and position, reset at every document boundary.
"""
from functools import lru_cache
import regex as re
import wordnet
from wordfreq import zipf_frequency

READS = ()
DISCOURSE = set("""
however therefore thus hence furthermore moreover nevertheless nonetheless
consequently alternatively additionally meanwhile finally similarly conversely
accordingly interestingly actually specifically indeed anyway also wait hmm
perhaps maybe например
""".split())
INTRODUCTIONS = (
    "for example", "for instance", "in particular", "in addition", "in fact",
    "of course", "as a result", "on the other hand", "in other words",
    "after all", "that is", "in short", "in conclusion", "by contrast",
    "in turn", "in some instances", "in reality", "on the contrary",
    "i mean", "e.g", "e.g.", "i.e", "i.e.",
)
COPULAS = set("""
is are was were be being been am becomes became become becoming
""".split())
PREPOSITIONS = set("""
in on at by of with for from to into onto over under through during without
within upon between among against after before around about using
""".split())
CONJUNCTIONS = set("and or but nor".split())
QUANTIFIERS = set("such what quite rather".split())
GERMAN_ARTICLES = set("ein eine einen einem einer eines".split())


@lru_cache(maxsize=16384)
def grammar(word):
    return wordnet.parts_of_speech(word)


@lru_cache(maxsize=16384)
def english_advantage(word):
    """Relative word familiarity, not a learned language classifier."""
    other = max(zipf_frequency(word, language)
                for language in ("de", "fr", "es", "pt", "it", "hu", "cs"))
    return zipf_frequency(word, "en") - other


def foreign_context(text):
    words = re.findall(r"[^\W\d_]+", text.lower())[-10:]
    return bool(words) and sum(map(english_advantage, words)) < -0.6 * len(words)


def code_context(text):
    return bool(re.search(r"[=\[\]{}]|\w\(", text[-80:]))


def comma(text, word, position):
    if position == 0:
        return -0.42
    value = 1.40
    value -= 0.41 * code_context(text)
    value -= 0.21 * word.isdigit()
    value -= 0.26 * ("adverb" in grammar(word))
    value -= 0.91 * (word in CONJUNCTIONS)
    value += 0.15 * word.endswith("s")
    value -= 0.66 * (position < 4)
    if word in DISCOURSE:
        value -= 1.14
    if any(text.lower().rstrip().endswith(p) for p in INTRODUCTIONS):
        value -= 1.27
    return max(-0.5, value)


def article(text, word, spelling, position):
    if position == 0:
        return -0.25 if spelling == "a" else -0.40
    value = 0.77
    value += 0.54 * ("verb" in grammar(word))
    value += 0.57 * (word in PREPOSITIONS)
    value -= 0.96 * (word in COPULAS)
    value -= 0.73 * (word in QUANTIFIERS)
    value -= 0.33 * (len(word) == 1 and word.isascii())
    value -= 0.70 * foreign_context(text)
    value -= 0.21 * code_context(text)
    value -= 0.23 * (spelling == "an")
    return max(-0.5, value)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text, position = ("", 0) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    stripped = token.strip()
    match = re.search(r"([^\W_]+)\W*$", text)
    word = match.group(1).lower() if match else ""
    value = 0.0

    if stripped == ",":
        value = comma(text, word, position)
        if "\n" in token:
            value = 0.34
        elif token.startswith(" "):
            value *= 0.60
    elif stripped in {"，", "、", "،"}:
        value = 1.05 if stripped == "，" else 0.87
        if stripped == "、":
            japanese = re.search(r"[\p{Hiragana}\p{Katakana}]", text)
            value = 1.28 if japanese else 0.08
        if position == 0:
            value = -0.42
    elif "," in stripped and len(stripped) <= 6:
        value = 0.48
        if stripped.startswith(")"):
            value = 0.97
        elif stripped.startswith(">"):
            value = 1.95
        elif stripped.startswith("]"):
            value = 0.85
        elif stripped.startswith("}"):
            value = -0.18
    elif stripped.lower() in {"a", "an"}:
        if token.startswith(" ") and stripped.islower():
            value = article(text, word, stripped, position)
        else:
            value = 0.23 if stripped[0].isupper() else 0.08
    elif stripped in GERMAN_ARTICLES and token.startswith(" "):
        value = 0.70
    elif ("\n" in token or "\\" in token) and ("{" in token or ":" in token):
        flow = r"\b(if|else|elif|for|while|switch|catch|try|except)\b[^{}\n]*$"
        if re.search(flow, text):
            value = 1.05
        elif re.search(r"[\"']:\s*$", token):
            value = 1.1
        else:
            value = 0.04
    return (doc, (text + token)[-180:], position + 1), float(value)

