COMMA_CHARS = ",，、،"
ARTICLES = {" a", " an", " A", " ein", " eine", " einer", " einem", " einen", " Ein", " un", " une", " una", " uno", " egy", " một", " uma"}
BOUNDARY = ".!?\n。"
TRANSITIONS = {
    "however", "therefore", "thus", "hence", "indeed", "furthermore", "moreover", "example",
    "instance", "alternatively", "wait", "yes", "so", "namely", "finally", "also", "instead",
    "consequently", "otherwise", "nevertheless", "besides", "additionally", "conversely",
    "similarly", "meanwhile", "first", "second", "then", "overall", "well", "now", "but",
}
PREPOSITIONS = {"with", "in", "by", "of", "to", "for", "from", "into", "on", "at", "over",
                "using", "use", "make", "have", "has", "had", "under"}
LINKERS = {"is", "was", "be", "are", "were", "and", "or", "as", "if", "that", "such", "also", "'s", "’s"}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok.strip() and tok.strip()[-1] in COMMA_CHARS:
        words = []
        for s in reversed(prefix.token_strings[:-1]):
            if any(c in s for c in BOUNDARY):
                break
            words.append(s.strip().lower())
        if words and words[0] in TRANSITIONS:
            return carry, 0.1
        if len(words) == 1:
            return carry, 0.65
        return carry, 1.2
    if tok in ARTICLES:
        w = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
        if w in PREPOSITIONS:
            return carry, 1.3
        if w in LINKERS:
            return carry, 0.45
        return carry, 0.8
    return carry, 0.0

