    if not any(c.isalnum() for c in text):
        if any(c in text for c in ')]}'):
            return 2.5 if '\n' in text else 0.0
        if text == "'":
            return 0.3
        if text.startswith(('\\', '_')):
            return 3.5
        if text.startswith(('"', '“', '‘', '【', '<')):
            return 7.0
        if text.startswith(('(', '[')):
            return 4.0
        if '\n' in text:
            return 3.0
        if text.startswith(','):
            return 1.7
        return 0.4
    if regex.fullmatch(r'\p{Latin}+', text):
        if len(text) == 1:
            return 0.8
        frequency = zipf_frequency(text, 'en')
        if text.istitle():
            return 2.3 if frequency < 4.0 else 0.7
        if text.isupper():
            return 1.8
        return 0.3 if frequency < 4.0 else 1.0
    return 1.3


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = opening_value(prefix.token_strings[-1])
        return (doc, token, value, True), value
    _, first_token, value, repeating = carry
    repeating = repeating and token == first_token
    return (doc, first_token, value, repeating), value if repeating else 0.0

programs.haiku:
"""First token of each document: how strongly the component fires, by what the token looks like.

The component is silent inside a document and fires on the first token of each document
(the first token of a packed row, and any token right after <|endoftext|>), because there
its only context is the token itself. Its size there depends on the token's kind:
  - programming keywords and preprocessor / comment openers (import, package, from, #include,
    /*, //, #pragma ...) fire strongly;
  - whitespace and line breaks, opening brackets and quotes, CJK and other non-Latin scripts,
    and special tokens fire moderately;
  - ordinary words that start with a space (" of", " the", " is") and digits sit near zero;
  - the bare letters j and J push it strongly negative.
Everywhere else the prediction is 0.
"""
READS = ()

CODE_WORDS = {"import", "from", "package", "export", "const", "var", "let", "static", "pub",
              "pragma", "typedef", "extern", "#include", "#define", "#ifndef", "#pragma", "#!/"}
CODE_WORDS_WEAK = {"use", "new", "mod", "private", "protected", "struct"}
OPENERS = {"#", "//", "/*", "/*\n", "/**\n", '"', "“", "<", "<?", "(", "[", "{", "**",
           '"""\n', "'''\n", "|", "&", "@"}


def _is_cjk_or_nonlatin(s):
    return any(0x3000 <= ord(c) <= 0x9FFF or 0xAC00 <= ord(c) <= 0xD7AF
               or 0x0E00 <= ord(c) <= 0x0E7F or 0x0600 <= ord(c) <= 0x06FF for c in s)


def token_value(s):
    """The activation predicted for a document's first token, given its text `s`."""
    t = s.strip()
    if s.startswith("<|") and s.endswith("|>"):
        return 11.8 if s == "<|endoftext|>" else 4.4
    if s != "" and set(s) <= set(" \n"):
        return 6.0                        # spaces and line breaks
    if "�" in s:
        return 5.0                        # half of a multi-byte character
    if _is_cjk_or_nonlatin(s):
        return 4.0
    if s in CODE_WORDS:
        return 10.0
    if s in CODE_WORDS_WEAK:
        return 4.5
    if s in OPENERS:
        return 6.0
    if t in OPENERS:
        return 4.0                        # opener after a space
    if "\n" in s:
        return 3.5                        # a symbol run ending in a line break
    if s in ("j", "J"):
        return -10.0
    if t.isdigit():
        return -0.3
    if s[:1] == " " and s[1:].isalpha():
        return -0.2                       # an ordinary word with its leading space
    if s.islower() and s.isalpha():
        return 0.7                        # word fragment without a space
    if s[:1].isupper() and s[1:].islower():
        return 1.0
    if not s.isalnum():
        return 0.5                        # other punctuation
    return 0.8


def step(carry, prefix, upstream):
    first = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not first:
        return None, 0.0
    return None, float(token_value(prefix.token_strings[-1]))

programs.sol:
"""A partial reconstruction of a boundary and source-code signal.

At document starts, use broad writing-system and word-frequency classes rather
than a vocabulary lookup. Elsewhere recognize extra spaces, JSON key openings,
code statements, printing calls, test names, member access, and LaTeX braces.
A title label at the very start is an especially strong boundary cue.
Individual vocabulary quirks at starts are deliberately not memorized.
"""
import unicodedata
import wordfreq

READS = ()


def beginning(s):
    w = s.strip()
    if s.startswith('<|'):
        return 0.0
    # Control characters and escaped control characters at a fresh start.
    if s == '\r':
        return 13.51
    if s == '\t':
        return 3.16
    if s == '\\t':
        return 7.51
    if s == '\\n':
        return 3.90
    if s == '\\"':
        return 8.50
    if s == '//\n':
        return 14.97
    if not w:
        return -0.65
    if w.isdecimal():
        return -2.43 if w == '0' else -0.58
    if w == 'package':  # namespace declaration at the start of a source file
        return -5.11
    if s == 'from':  # Python's import-from form
        return -3.60
    if s == '··':
        return 2.93
    if all(not c.isalnum() for c in w):
        return -0.75
    if w.isascii() and w.isalpha():
        lower = w.lower()
        if lower == 'the':
            return 2.30
        if lower in ('a', 'an'):
            return 0.55 if w == 'A' else 3.15
        if lower in ('this', 'that', 'these', 'those'):
            return 0.40
        if lower in ('my', 'your', 'his', 'her', 'its', 'our', 'their'):
            return 3.38
        if lower in ('of', 'to', 'in', 'on', 'at', 'with', 'by', 'for',
                     'from', 'into', 'onto', 'upon', 'about', 'as',
                     'over', 'under', 'between'):
            return 0.95
        frequency = wordfreq.zipf_frequency(w, 'en')
        return 1.65 if frequency >= 4.0 else 0.35
    if w.isascii():
        return 1.18
    names = [unicodedata.name(c, '') for c in w]
    if any('CYRILLIC' in name for name in names):
        return -1.64
    if any('CJK' in name for name in names):
        return 0.55
    return -1.03


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc or carry[1] == '<|endoftext|>'
    if fresh:
        return (doc, s, s, s, 1), beginning(s)
    # The fourth field survives only while the initial token keeps repeating.
    _, previous, tail, initial, position = carry
    value = 0.0
    w = s.strip()
    p = previous.strip()
    if position == 1 and initial == 'Title' and s == ':':
        value = 21.30
    elif s == initial and s in ('\r', '\t', '\\t', '\\n'):
        value = beginning(s)
    elif s == '··' and initial == '··':
        value = 2.93
    elif s == ' ':
        if previous == ' ':
            value = 0.50
        elif previous.isspace():
            value = 0.90 if '\n' in previous else 1.05
        elif previous.endswith(('\n', '\r')):
            value = 0.90
        elif tail.endswith('\\n'):
            value = 2.0
    elif s in (' "', " '"):
        if previous.endswith(('\",', "',")):
            value = 1.05 if s == ' "' else 0.55
        elif previous.isspace() and '\n' not in previous:
            value = 0.60
    elif w in ('return', 'const', 'let', 'var', 'throw', 'break'):
        boundary = (previous.isspace() or previous.endswith(('\n', '\r'))
                    or tail.endswith(('\\n', '\\t'))
                    or p.endswith((';', '{', '}')))
        if boundary:
            value = 1.36 if w == 'return' else 1.10
            if w in ('throw', 'break'):
                value = 0.65
        elif w == 'return' and p.endswith(')'):
            value = 1.45
    elif w in ('print', 'printf', 'println', 'cout'):
        boundary = (previous.isspace() or previous.endswith('\n')
                    or tail.endswith(('\\n', '\\t'))
                    or p.endswith((';', '{', ':')))
        value = 0.95 if boundary or w == 'cout' else 0.20
    elif s in ('.log', '.println', '.Println', '.Printf', '.WriteLine'):
        if p in ('console', 'Console', 'fmt', 'out', 'System'):
            value = 1.20 if s == '.log' else 0.90
    elif s == '.out' and p == 'System':
        value = 2.0
    elif (s.endswith('.') and ('()' in s or
                              any(c in s for c in ('"', "'")) and ')' in s)
          or s.endswith('->') and any(c in s for c in ')]}')):
        value = 1.20
    elif s == '``' and previous == '\xa0':
        value = 0.95
    elif w.lstrip('/.').lower() in ('test', 'tests'):
        value = 0.08 if s.startswith(' ') and w.islower() else 0.28
    elif s == '->':
        value = 0.50
    elif s == '{' and p in ('begin', 'end'):
        value = 1.65 if p == 'begin' else 1.0
    elif s in (' .', ' <', ' $') and previous.isspace():
        value = {' .': 1.2, ' <': 1.45, ' $': 0.95}[s]
    elif w == 'void' and p == 'public':
        value = 0.85
    return (doc, s, (tail + s)[-32:], initial if initial == s else None,
            position + 1), value

programs.haiku:
"""layers.1.mlp.down_proj:1835, a readable approximation of one MLP down-projection component.

Activation is near 0 almost everywhere and large in a few kinds of place. The program
predicts it with four rules:

1. First token of a document (the token right after <|endoftext|>, where attention has
   no earlier context): a word in Latin letters, optionally with a leading space, gives
   about +1.4. Digits, punctuation and non-Latin text give about -0.7. A document that
   opens with "package" gives about -5.
2. In code: a lone space that starts an indented line (it follows an indentation
   token or a newline) gives about +0.9.
3. In code: return and output statements (" return", "\treturn", " print", ".println",
   "cout", ".log", "printf") give about +1.0 to +1.2. Closers of a call chain such as
   "()." and '").' give about +1.4. Declarations (const, let, var, void) give about +0.6.
4. Everything else is 0.

Rules 2 and 3 match the token's text (rule 2 also looks at the previous token); they do not
check that the surrounding text really is code, so prose uses of the same words also match.
"""

import re

READS = ()

RETURN_TOKENS = {" return", "\treturn", "return"}
PRINT_TOKENS = {" print", ".println", ".Println", "cout", " cout", ".out", ".log", "printf", " printf"}
CHAIN_TOKENS = {"().", '").', "').", '"].', "'].", "()).", '")->', "')->"}
DECL_TOKENS = {" const", "\tconst", " var", "\tvar", " let", " void"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        if s == "package":
            return None, -5.0
        if re.fullmatch(r" ?[A-Za-z]+", s):
            return None, 1.4
        if re.fullmatch(r"\s*[0-9]+|[^A-Za-z\s]+", s):
            return None, -0.7
        return None, 0.0
    if s == " ":
        before = prefix.token_strings[-2]
        if before.strip() == "" or before.endswith("\n"):
            return None, 0.9
        return None, 0.0
    if s in RETURN_TOKENS:
        return None, 1.2
    if s in PRINT_TOKENS:
        return None, 1.0
    if s in CHAIN_TOKENS:
        return None, 1.4
    if s in DECL_TOKENS:
        return None, 0.6
    return None, 0.0

programs.sol:
"""A detector for single-quotation marks and their typographic variants.

Single quotes and primes are positive; contractions and closing punctuation
are weaker. Two consecutive single quotes used as a double quote are negative,
but empty code strings and triple-quoted strings are not. The rules also
recognize a few escaped spellings and use a separate document-start baseline.
"""
import codecs
import re

READS = ()
CONTRACTIONS = {'s', 't', 'm', 're', 've', 'll', 'd'}
SINGLE_MARKS = "'‘’′ʻʼ＇ˈ´"
CODE_DELIMITERS = '=,:([{|?'


def activation(token, history, previous, first):
    if first:
        if token == '\t':
            return -3.7
        if token.startswith('\t'):
            return -1.5
        return 0.13 if token[:1].isdigit() else -0.26
    ending = history[-32:] + token
    if token == 'prime' and previous.endswith('\\'):
        return 1.65  # LaTeX's prime mark
    if token and re.search(r'(?:&#34|\\x94)$', ending):
        return -1.4  # escaped double quote or em dash
    if token and re.search(r'(?:&#39|&[lr]squo|\\x9[89])$', ending):
        return 0.95
    if '『' in token:
        return 1.1
    if '』' in token:
        return 0.68
    if '《' in token:
        return 0.4
    marks = [c for c in token if c in SINGLE_MARKS]
    if not marks:
        return 0.11 if '``' in token else -0.001
    mark = marks[-1]
    before, after = token.split(mark, 1)
    adjacent = (previous + before).rstrip()
    code_before = adjacent.endswith(tuple(CODE_DELIMITERS))
    code_before |= previous.strip() in {'return', 'or', 'else'}
    if token.startswith(mark) and previous.endswith(mark):
        if previous.endswith(mark * 2):
            return 0.58  # completing a triple quote
        if mark == "'" and previous[:-1].rstrip().endswith(
                tuple(CODE_DELIMITERS)):
            return 0.65
        return -4.6  # second mark of a typographic double quote
    if len(marks) >= 3:
        return 0.58
    if len(marks) == 2 and mark * 2 in token:
        suffix = token.split(mark * 2, 1)[1]
        if before in {'.', ','}:
            return -1.1
        empty = code_before or (bool(before) and before.isspace()
                                and any(c in suffix for c in ')]};,'))
        if mark == "'" and empty:
            return 0.65
        return -2.6
    if after.lower() in CONTRACTIONS:
        return 0.05
    if any(c.isalpha() for c in after):
        return 0.26
    if mark == '′':
        return 1.65
    if mark in 'ʻʼ＇ˈ´':
        return 1.1
    if '\n' in token:
        return 0.4
    if after.strip():
        return 0.54
    return 1.35 if mark == '‘' else 0.95


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    history, previous, pending = ('', '', b'') if first else carry[1:]
    raw = pending + prefix.token_bytes[-1]
    token, used = codecs.utf_8_decode(raw, 'replace', False)
    value = activation(token, history, previous, first)
    state = (doc, (history + token)[-32:], token, raw[used:])
    return state, value

"""A lexical approximation of a presence, contents and placement signal.

Training peaks often describe what something has, contains, or is equipped
with. These rules target that pattern, not token-specific background offsets.

WordNet supplies English inflections. Word-family scores are adjusted for
local grammar: 'there is', possession, object-introducing articles, and
locative prepositions. A few non-English presence/location markers and
end-of-text markers have separate scores. This does not model longer context.
"""
from functools import lru_cache
import wordnet

READS = ()

# Each family has a score and dictionary headwords, not tokenizer IDs.
FAMILIES = {
    'contain': (0.71, 'contain'),
    'include': (0.18, 'comprise consist encompass include'),
    'house': (0.33, 'accommodate house'),
    'offer': (0.36, 'offer'),
    'provide': (0.00, 'afford furnish provide supply'),
    'feature': (0.17, 'boast feature'),
    'have': (0.19, 'have'),
    'own': (0.17, 'own possess'),
    'support': (0.24, 'support'),
    'exist': (0.00, 'available exist present remain'),
    'location': (0.20, 'locate situate'),
    'situate': (0.69, 'situate'),
    'placement': (0.00, 'dispose fit install place position'),
    'installation': (0.66, 'equip mount'),
    'operation': (0.19, 'operate run'),
    'attachment': (0.22, 'adjacent attach connect'),
    'display': (0.20, 'display exhibit publish'),
    'posture': (0.18, 'hang lie live sit stand'),
    'carry': (0.22, 'carry hold'),
    'wear': (0.19, 'bear wear'),
    'keep': (0.17, 'keep maintain retain store'),
    'host': (0.28, 'host serve'),
    'come': (0.31, 'come'),
    'size': (0.18, 'big huge large small tiny vast'),
    'free': (0.17, 'free'),
    'naming': (-0.07, 'call name title'),
    'presence_noun': (0.00, 'availability existence presence proximity vicinity'),
}

# Function words also provide flags for the grammatical rules below.
WORDS = {
    'there': (0.33, 'there'),
    'addition': (0.11, 'additionally also furthermore moreover too'),
    'restrictor': (-0.13, 'merely only solely'),
    'foreign_also': (0.37, 'anche auch aussi también também также'),
    'foreign_have': (0.56, 'có possui tem tiene tienen tinha имеет имеют содержит'),
    'russian_exist': (1.41, 'есть'),
    'already': (0.00, 'already currently still'),
    'be': (0.00, "'s am are be been being is was were ’s"),
    'indefinite': (0.00, 'a an'),
    'with': (0.08, 'with'),
    'of': (0.00, 'of'),
    'in': (0.00, 'in'),
    'on': (0.00, 'at on'),
    'by': (0.00, 'by'),
    'pronoun': (0.00, 'he i it she they we you'),
    'modal': (0.00, 'can could may might must should will would'),
    'negation': (0.00, "'t n't never no not ’t"),
}
FAMILIES = {k: (v, frozenset(s.split())) for k, (v, s) in FAMILIES.items()}
WORDS = {k: (v, frozenset(s.split())) for k, (v, s) in WORDS.items()}
CONTENTS = {
    'contain', 'include', 'house', 'offer', 'feature', 'have', 'own',
    'support', 'carry', 'wear', 'exist', 'placement', 'installation',
    'provide', 'keep', 'host',
}
PLACEMENT = {'location', 'placement', 'installation', 'house', 'carry', 'wear'}


@lru_cache(maxsize=100000)
def classify(s):
    word = s.strip().lower().lstrip('-')
    flags, value = set(), 0.
    if word.isascii() and word.isalpha():
        flags.add('word')
        if word.endswith('s'):
            flags.add('s_ending')
        forms = set(wordnet.base_forms(word)) | {word}
        for name, (score, words) in FAMILIES.items():
            if forms & words:
                flags.add(name)
                value += score
