    for name, (score, words) in WORDS.items():
        if word in words:
            flags.add(name)
            value += score

    if '有' in word:                 # Chinese possession/existence
        value += 0.37
    if any(c in word for c in '设設置存含具备備附挂掛摆擺'):
        value += 0.25                 # setting, containing, attaching
    if any(c in word for c in '着著'):
        value += 0.55                 # durative/state marker
    if word in {'に', 'には', 'にある'}:
        value += 0.49                 # Japanese locative constructions
    if 'ある' in word:
        value += 0.32                 # Japanese existence verb
    if word == '에':
        value += 0.65                 # Korean location particle
    if word.endswith(('ся', 'сь')):
        value += 0.50                 # Russian reflexive/passive ending
    if s == '<|endoftext|>':
        value += 1.34
