def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_doc = carry is not None and carry[0] != doc
    first = carry is None or new_doc
    previous, earlier = ('', '') if first else carry[1:]
    s = prefix.token_strings[-1]
    c, value = classify(s)
    p, _ = classify(previous)
    pp, _ = classify(earlier)

    if first:
        value -= 0.16 + (0.06 if 'word' in c else 0.)
    if new_doc:
        value += -0.15 + (0.10 if 'word' in c else 0.)
    if 'there' in p and 'be' in c:
        value += 0.81
    if c & CONTENTS:
        if p & {'addition', 'already'}:
            value += 0.58
        if 's_ending' in c:
            value += 0.22
    if c & PLACEMENT and 'be' in p:
        value += 0.17
    if 'be' in c and 'pronoun' in p:
        value -= 0.09
    if 'have' in c:
        if 'pronoun' in p:
            value += 0.09
        if 'modal' in p:
            value += 0.17
        if 'negation' in p:
            value += 0.57
    if 'addition' in c:
        if p & {'be', 'pronoun'}:
            value += 0.14
        if 'there' in pp:
            value += 0.67
    if 'indefinite' in c:
        if p & CONTENTS:
            value += 0.50
        if p & {'with', 'by'}:
            value += 0.27
        if 'addition' in p:
            value += 0.42
        if 'be' in p and 'there' in pp:
            value += 0.57
    if 'with' in c and p & {'come', 'placement', 'installation'}:
        value += 0.68
    if c & {'in', 'on', 'of'}:
        if 'location' in p:
            value -= 1.17
        if 'presence_noun' in p:
            value += 0.40
    return (doc, s, previous), value

