"""Layer-1 MLP down-projection component 1839: a "composition" detector.

The component fires on the word that introduces what something has, contains, houses or is
fitted with, and on the article right after it:
  * strongest on verbs of containing and equipping ("contains", "houses", "equipped",
    "mounted", "situated", "offers", "features"), and on their translations ("有", "包含",
    "есть", "tiene");
  * weaker on plain "has", "have", "had", "also", "there", "include(s)";
  * on "there is/are/'s" and the article after a possession word ("has a", "with a",
    "there is also a", "equipped with a");
  * a composition participle followed by with/by/of ("equipped with", "accompanied by",
    "consisted of") is positive too;
  * negative on the preposition after a verb of location or origin ("located in",
    "founded in", "designed by", "published in"), a place or source rather than contents;
  * the end-of-text token is high, and the first token of a document is mildly negative.
Everything else is about zero. Values are rounded mean activations on training text.
"""

READS = ()

END = "<|endoftext|>"

# Verbs of containing, housing, equipping or offering (activation about 1), and translations.
STRONG = {
    " contains", " contain", " containing", " contained", " houses", " housed", " equipped",
    " mounted", " situated", " bearing", " operates", " hosted", " hosting", " wears", " wear",
    " sits", " supports", " serves", " comprises", " comprise", " consists", " carries",
    " carried", " carry", " offers", " offer", " boasts", " maintains", " owns", " possesses",
    " featuring", " featured", " runs", " hangs",
    "着", "设置", "挂", "还有", "包含", "摆放", "装备", "拥有", "含", "附", "设", "設", "搭", "摆",
    "有一个", "有一", "装饰", "包含了", "есть", "находится", "содержит", "tiene", "contiene",
    "にある",
}
