WEAK = {
    " have", " has", " had", " having", " also", " there", " There", " include", " includes",
    " features", " feature", " house", " host", " included", " including", "有", "也有", "都有",
}
# Verbs of location or origin, after which "in", "at", "by", "to" give a negative value.
LOCATION_PARTICIPLES = {
    " located", " founded", " established", " released", " formed", " built", " shown", " born",
    " lived", " appeared", " published", " directed", " interested", " served", " based",
    " situated", " due", " according", " designed", " developed", " created",
}
# Composition participles, followed by "with", "by", "of" or "to" (equipped with, followed by).
COMPOSITION_PARTICIPLES = {
    " equipped", " fitted", " filled", " accompanied", " followed", " surrounded", " consisted",
    " connected", " coupled", " served", " adorned", " supplied", " provided", " lined",
    " topped", " decorated", " packed", " stocked",
}
BE = {" is", " are", " was", " were", "'s", "’s", " 's"}
ARTICLES = {" a", " an", " the", " one", " some", " many", " several", " no", " any", " also"}
# Words after which an article reads as the start of a possession ("has a", "with a").
POSSESSIVE = STRONG | WEAK | {" with", " adorned", " accompanied", " followed"}
PREPOSITIONS = {" in", " at", " on", " by", " to", " from", " of", " since", " than"}
COMPOSITION_PREPOSITIONS = {" with", " by", " of", " to"}


def step(carry, prefix, upstream):
    now = prefix.token_strings[-1]
    before = prefix.token_strings[-2] if len(prefix) > 1 else None
    new_document = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if now == END:
        value = 1.35
    elif new_document:
        value = -0.22
    elif before in LOCATION_PARTICIPLES and now in PREPOSITIONS:
        value = -0.6
    elif before in COMPOSITION_PARTICIPLES and now in COMPOSITION_PREPOSITIONS:
        value = 0.8
    elif before in ("there", "There") and now in BE:
        value = 0.82
    elif now in STRONG:
        value = 1.0
    elif now in WEAK:
        value = 0.3
    elif before in POSSESSIVE and now in ARTICLES:
        value = 0.3
    else:
        value = 0.0
    return carry, value

