"""Detect star spellings and symbols, including ones split across tokens.

This is primarily a spelling detector, not an astronomy classifier.  It also
responds to short st-a / st-r continuations in unrelated words.  The text glyphs
★, ☆, ⋆ and Chinese 星 are positive; regex repetition after an escaped
character class is negative. End-of-text has a separate, steady response.
A document-opening Title: field has its own response. Only a short byte
tail and the previous token are remembered.
"""

import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=8192)
def latin(text):
    if any('CYRILLIC' in unicodedata.name(c, '') for c in text):
        return anyascii(text).lower()
    return text.lower()


def response(token, previous_token, previous_text, initial):
    word = token.strip()
    bare = word.lstrip('-/_')
    low = bare.lower()
    if word == '<|endoftext|>':
        return -2.13 if initial else 1.335
    if word and all(c in '★☆⋆' for c in word):
        if '☆' in word:
            return 2.65
        return 8.0 if '⋆' in word else 4.7
    if word == '星':
        return 6.9
    if '明星' in word or word.endswith('之星'):
        return 5.3
    if word in ('星级', '星級'):
        return 5.1
    if '星' in word:
        return 1.4
    if low == 'star':
        last_word = re.search(r'(\w+) *$', previous_text)
        last_word = last_word[1] if last_word else ''
        if last_word.lower() in ('all', 'energy'):
            return 10.8 if word.startswith('-') else 9.4
        if word.startswith('-') and bare.istitle():
            return 11.0
        if bare.istitle():
            return 6.0 if last_word.istitle() else 3.9
        if bare.isupper():
            return 5.1
        if word != bare:
            return 4.7
        return 4.1 if token.startswith(' ') else 7.0
    if low == 'stars':
        if previous_text.rstrip()[-1:].isdigit():
            return 6.0
        return 4.7 if bare.istitle() else 3.1
    if low in ('starring', 'starred'):
        return 3.4
    if low.endswith('star') and not token.startswith(' '):
        return 2.0

    # Short st fragments can combine with the newest letters across a boundary.
    p = latin(previous_token).strip(' -_./\\\t\n()[]{}')
    s = latin(token)
    if re.fullmatch(r'(?:[aeiou]|in)?st', p) and token[:1].isalpha():
        if re.search(r'star(?:s|ring|r|g)?$', p + s):
            return 7.9
        if re.search(r'stat(?:s)?$', p + s):
            return 3.6
        if (p + s).endswith('start'):
            return 3.0
        if s.startswith('r'):
            return 0.6
        return 0.2
    if p.endswith('star') and s == 'red':
        return 4.5
    if previous_text.endswith('С') and token.startswith('тар'):
        return 8.1
    if previous_text.endswith('С') and token.startswith('т'):
        return 2.7
    if previous_text.endswith('ス') and token.startswith('タ'):
        return 2.7
    if previous_text.endswith('스') and token.startswith('타'):
        return 11.0
    if word == 'ー' and previous_text.endswith(('スタ', 'スト', 'ステ')):
        return 3.6
    if word == 'スタ':
        return 1.3
    if token.startswith(('*', '+')):
        escaped_class = re.search(r'\\([sdwt])\\*$', previous_text)
        if escaped_class:
            return -6.2 if escaped_class[1] == 's' else -2.4
    if token == ':' and previous_text == 'Title':
        return 5.26
    return 0.001


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    initial = carry is None or carry[0] != document
    _, tail, previous = (document, b'', '') if initial else carry
    newest = prefix.token_bytes[-1]
    before = tail.decode('utf-8', 'ignore')
    combined = (tail + newest).decode('utf-8', 'ignore')
    token = combined[len(before):]
    value = response(token, previous, before, initial)
    return (document, (tail + newest)[-64:], token), value

"""Approximate example and value introducers, using local text rather than token IDs.

Positive rules cover 'such as', example-like uses of 'like', mapping keys,
assignment, return, documentation parameters, and member-access punctuation.
Braces, indentation and quotes separate mapping colons from prose, control
statements and type declarations.  TeX row breaks are another positive case;
namespace separators and repeated middle-dot fillers have negative rules.
Everything else is near zero.  This leaves ordinary lexical fluctuations
unmodeled.  Keep only 400 trailing characters, reset for each packed document.
"""
import re

READS = ()

VERBAL_LIKE = {
    'look', 'looks', 'looked', 'looking', 'seem', 'seems', 'seemed',
    'sound', 'sounds', 'sounded', 'feel', 'feels', 'felt', 'smell',
    'smells', 'taste', 'tastes', 'would', 'could', 'might', 'should',
    'i', 'you', 'we', 'they', 'he', 'she', 'it', 'really', 'also',
    'not', "don't", "doesn't", 'and', 'the', 'just', 'was', 'is',
    'be', 'been', 'go', 'goes', 'went', 'as', 'do', 'did',
    'me', 'him', 'her', 'us', "i'd", "you'd", "we'd", "they'd",
}


def last_line(text):
    line = re.split(r'\n|\\+n', text)[-1]
    return re.sub(r'\\+t', '\t', line)


def predict(s, before):
    word = s.strip().lower()
    if word in ('as', 'like', 'than'):
        words = re.findall(r"[a-z]+(?:'[a-z]+)?", before.lower().replace("’", "'"))
        prev = words[-1] if words else ''
    if word == 'as':
        if prev == 'such':
            return 0.75
        if 'such' in words[-4:]:
            return 0.32
        return 0.0
    if word == 'like':
        verbal = prev in VERBAL_LIKE or prev.endswith(("n't", "'d"))
        return -0.025 if verbal else 0.52
    if word == 'than':
        return 0.56 if prev == 'other' else 0.0
    if word.lstrip('@') in ('param', 'returns', 'return'):
        if word.startswith('@') or before.rstrip().endswith(('@', '\\', '<')):
            return 1.02 if word.endswith('param') else 0.85
    if word == ':=':
        return 0.62 if re.search(r'\w+\s*,\s*\w+\s*$', before) else 0.39
    if word == '=' and s.startswith(' '):
        return -0.05
    if word == '<-':
        return 0.60
    if word == 'impl':
        return 0.74
    if word == 'return':
        line = last_line(before)
        if s.startswith('\t'):
            java_method = re.search(r'\b(?:public|private|protected)\b', before)
            return 0.70 if java_method else 0.42
        if re.fullmatch(r'[\s\d]*', line) or re.search(r'[;{}]\s*$', line):
            return 0.40
        return -0.04
    if word == '::':
        return -0.12
    if ':' in s and re.fullmatch(r'[\s\\\'":]+', s):
        if s.strip().startswith(':') and s.startswith(' '):
            return -0.08
        line = last_line(before)
        if re.search(r'\b(?:if|elif|while|case)\b', line):
            return 0.0
        # Do not confuse an object's values with CSS or interface types.
        header = last_line(before[:before.rfind('{')]) if '{' in before else ''
        if (re.search(r'\b(?:interface|class)\b', header)
                or re.match(r'\s*[.#]', header)):
            return 0.0
        quoted = '"' in s or "'" in s
        if quoted and not s.rstrip().endswith(':'):
            return 0.18  # The token already includes the value's opening quote.
        key = re.search(r'[\w$]+$', before)
        head = before[:key.start()].rstrip(' \t\n\r\\"\'') if key else ''
        first_key = head.endswith('{')
        if quoted:
            value = 0.75 if first_key else (0.50 if '{' in before else 0.25)
            return value + (0.18 if '\\' in s else 0.0)
        if '\n' in s:
            return 0.0
        if first_key:
            return 0.75
        indented = re.fullmatch(r'\s+(?:\d+\s+)?[\w$]+', line)
        after_comma = head.endswith(',')
        if (indented or after_comma) and '{' in before:
            if line.strip() not in ('else', 'try', 'finally', 'default'):
                return 0.57
        return 0.0
    if word == '=>':
        return 0.62 if before.rstrip().endswith(("'", '"')) else 0.14
    if s.endswith('().'):
        return 0.36
    if s == ' .' and re.fullmatch(r'[\s\d]*', last_line(before)):
        return 0.50
    if s == '.' and before.lower().endswith('e.g'):
        return 0.32
    if word.startswith('··') and set(word) == {'·'}:
        return -0.76
    if word.startswith('\\') and set(word) == {'\\'}:
        tex = re.search(
            r'(?<!\\)\\(?:frac|sqrt|lim|sum|int|begin|left|right|text|color)(?![A-Za-z])',
            before,
        )
        if len(word) >= 4 or (len(word) == 2 and tex):
            return 0.85
        if len(word) == 2:
            return -0.12
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before = ''
    else:
        before = carry[1]
    s = prefix.token_strings[-1]
    value = predict(s, before)
    return (doc, (before + s)[-400:]), value

"""Detect the short spelling/sound 'ba', including across a token boundary.

The response is strongest to a short ba fragment, weaker inside a longer
word, and weaker for spaced, complete words. A few scripts have their own
scale. Common English words and Spanish imperfect -aba endings are
downweighted. Also recognize a document's initial 'Title:' label. Ordinary
lexical variation and most small background activations are left out.
"""
import unicodedata
from functools import lru_cache
import regex
from pypinyin import lazy_pinyin
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=65536)
def spelling(raw):
    text = unicodedata.normalize('NFKD', raw).lower()
    return ''.join(c for c in text if not unicodedata.combining(c))


@lru_cache(maxsize=65536)
def local_value(raw):
    text = spelling(raw)
    letters = text.strip().lstrip('._/\\-')
    if '吧' in text:
        return 5.9
    if '巴' in text:
        return 3.3 if len(text.strip()) == 1 else 0.5
    if len(text.strip()) == 1 and any(lazy_pinyin(c)[0] == 'ba' for c in text
           if regex.fullmatch(r'\p{Script=Han}', c) and c != '把'):
        return 0.9
    if '钡' in text or '鋇' in text:  # Barium, whose symbol is Ba.
        return 2.1
    if 'ば' in raw or 'バ' in raw:
        return 1.25 if len(raw.strip()) == 1 else 0.05
    if '바' in raw:
        return 2.5 if len(raw.strip()) == 1 else 0.2
    if 'با' in text:
        return 2.0 if text.strip() == 'با' else 0.2
    if 'ба' in text:
        return 0.9 if text.strip() == 'ба' else 0.1
    if raw == 'AB':
        return 1.2
    if 'ba' not in letters:
        return 0.0
    if letters == 'mba':  # The degree abbreviation.
        return 5.7
    if letters.endswith('ba') and len(letters) <= 3:
        value = 4.5 if len(letters) == 2 else 3.5
        accented = any(unicodedata.combining(c)
                       for c in unicodedata.normalize('NFKD', raw))
        return value * (0.2 if accented else 1.0)
    tail = letters.split('ba', 1)[1]
    if len(letters) <= 4 and tail.startswith('u'):
        return 2.8
    if letters == 'bah':
        return 4.5 if not raw.startswith(' ') else 2.0
    value = 0.8 if len(letters) <= 4 else 0.15
    if raw.startswith(' '):
        value *= 0.4
    if zipf_frequency(letters, 'en') > 4.5:
        value *= 0.2
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0)
    _, previous, position = carry
    raw = prefix.token_strings[-1]
    text = spelling(raw)
    value = local_value(raw)
    letters = text.lstrip('._/\\-')
    if previous.endswith('b') and letters.startswith('a'):
        n = len(letters)
        crossing = 4.5 if n == 1 else 1.3 * local_value('b' + letters)
        if any(unicodedata.combining(c)
               for c in unicodedata.normalize('NFKD', raw)):
            crossing *= 0.2
        value = max(value, crossing)
    if text == 'aba':
        stem = regex.search(r'[a-z]+$', previous)
        if stem and zipf_frequency(stem[0] + 'aba', 'es') > 2.0:
            value = 0.0  # Spanish imperfect-tense ending, not a ba fragment.
    if position == 1 and previous == 'title' and raw == ':':
        value = 12.04
    return (doc, text, position + 1), value

