"""A fading signal for E-initial words, including Greek/Cyrillic E and
E-sounding Japanese transcriptions. Training examples suggest the fact
that a word began with E persists across its early continuing pieces.
English frequency and piece length give coarse strengths, without a
token lookup table. Also follows scientific notation and the technical
phrases "exit code" and "expected value".
"""
from functools import lru_cache
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
RUN = regex.compile('|'.join(
    rf'(?P<{name}>[\p{{{script}}}{extra}]+)$'
    for name, script, extra in (
        ('latin', 'Latin', ''), ('cyrillic', 'Cyrillic', ''),
        ('greek', 'Greek', ''), ('katakana', 'Katakana', 'ー'))))

@lru_cache(maxsize=8192)
def part(s):
    m = RUN.search(s)
    return (m.lastgroup, m.group(), m.start()) if m else ('', '', 0)

@lru_cache(maxsize=8192)
def frequency(s):
    return zipf_frequency(s, 'en')


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
