    continues = bool(fragment and old and start == 0 and script == old_script)
    if continues and old[-1].islower() and s[0].isupper():
        continues = False
    word = old + fragment if continues else fragment
    value = 0.0
    if word and anyascii(word[0]).lower().startswith('e'):
        before = len(old) if continues else 0
        length = len(fragment)
        if script in ('latin', 'cyrillic'):
            if before == 0:
                f = frequency(word)
                value = 0.54 if f <= 1.5 else 0.23 if f <= 3.5 else 0.08
                if not word.isascii():
                    value = 0.08
            elif before <= 3:
                if frequency(s) <= 2.5:
                    value = 1.02 if length <= 5 else 0.51
                else:
                    value = 1.77 if length <= 2 else 1.32
            else:
                value = (0.8 if length <= 2 else 0.56) if before <= 5 else (
                    0.35 if before <= 8 else 0.12)
        else:
            pulse = ((0.25, 0.8, 1.45, 0.9, 0.38) if script == 'greek'
                     else (-0.15, 1.8, 2.9, 0.8, 0.2))
            value = pulse[before] if before < len(pulse) else 0.05
    if (last.strip(), s.strip()) == ('exit', 'code'):
        value = 1.5
    elif (last.strip(), s.strip()) == ('expected', 'value'):
        value = 1.2
    # A second brief pulse follows a numeric exponent's e, sign and digits.
    if s in ('e', 'E') and last[-1:].isdigit():
        value, exponent = 0.75, 1
    elif exponent == 1 and s in ('-', '+'):
        value, exponent = 2.24, 2
    elif exponent in (1, 2, 3) and s.isdigit():
        value = 1.13 if last == '-' else 0.97 if last in ('e', 'E') else 0.2
