_numbers = inflect.engine()
ORDINALS = {_numbers.number_to_words(_numbers.ordinal(n)): n
            for n in range(1, 13)}
# School examination boards, entrance examinations, and testing institutions.
EXAMS = {
    'gmat': 4.2, 'gre': 2.4, 'usmle': 3.3, 'ielts': 4.3,
    'ncert': 10.7, 'cbse': 10.3, 'icse': 6.1, 'gcse': 12.5,
    'igcse': 10.1, 'iit': 6.3, 'jee': 7.5, 'neet': 9.1,
    'upsc': 6.5, 'iift': 4.5, 'егэ': 8.5,
}
HAN_SCHOOLS = {'小学': 2.8, '中学': 1.7, '初中': 4.8, '高中': 4.0}


def school_year(n, class_label=False):
    # Numbered classes have their strongest response at secondary-school ages.
    if n <= 5:
        return 0.7 * n + 1.0 if class_label else 0.4 * n + 2.5
    if n <= 9:
        return 1.15 * n + (2.2 if class_label else 0.4)
    return 11.5 if class_label else 6.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
