    education = bool(re.search(
        r'\b(?:math|mathematics|algebra|geometry|science|trigonometry|exam|'
        r'school|grade|class|subjects|students|worksheet|problems|diagrams)s?\b',
        before, re.I))

    if word in {'school', 'schools', '-school'}:
        value = SCHOOL_LEVELS.get(prev, 0.2)
        if word == 'schools':
            value *= 0.55
    elif word in {'grade', 'grades', '-grade', 'grad', 'gr'}:
        m = re.search(r'(\d{1,2})\s*(?:st|nd|rd|th)\s*$', before)
        n = int(m[1]) if m else 0
        n = ORDINALS.get(prev, n)
        if 1 <= n <= 12:
            value = n + 2.0 if n <= 3 else min(n + 1.2, 9.5)
            if word in {'grad', 'gr'}:
                value = value + 3.0 if token.strip().islower() else 0.0
    elif word in {'high', 'secondary'} and prev in {'junior', 'senior', 'higher'}:
        if word == 'high':
            value = 9.8 if prev == 'junior' else 6.5
        else:
            value = 10.5 if prev == 'senior' else 8.5
    elif word == 'old' and re.search(r'\byears?$', before):
        value = 1.0
    elif word == '-old' and re.search(r'\byear$', before):
        value = 1.1
    elif word == 'people' and prev == 'young':
        value = 0.85
    elif word == 'league' and prev == 'junior':
        value = 1.0
    elif word in {'kindergarten', 'classmates', 'elementary'}:
        value = 1.4
    elif word == 'primary':
        value = 0.4
    elif word == 'middle':
        value = 0.0 if prev == 'the' else 0.6
    elif word == 'education' and prev in {'higher', 'secondary', 'primary'}:
        value = 0.6
    elif word == 'core' and prev == 'common':
        value = 5.0
    elif word == 'stage' and prev == 'key':
        value = 7.0

    # Names can be completed in the middle of a multi-token word.
    lower_end, lower_before = end.lower(), before.lower()
    for name, response in EXAMS.items():
        start = len(end) - len(name)
        spelling = end[start:]
        if (lower_end.endswith(name) and not lower_before.endswith(name)
                and (start == 0 or not end[start - 1].isalpha())
                and (spelling.isupper() or spelling.islower())):
            value = response
    if re.search(r'\b[Aa]ptitude$', end):
        value = 1.8

    m = re.search(r'\b(class(?:es)?|grades?|years?|ages?|aged)\s+'
                  r'(?:\d{1,2}\s*(?:[-–]|to|through)\s*)?(\d{1,2})$', end, re.I)
    if token.isdigit() and m and 1 <= int(m[2]) <= 12:
        n = int(m[2])
        if m[1].lower().startswith(('age', 'aged')):
            value = 2.7 if 6 <= n <= 9 else 0.5
            if m[1].lower() == 'ages' and 6 <= n <= 9:
                value = 6.0
            if n >= 10:
                value = 3.5 if m[1].lower() != 'aged' else 2.0
        elif m[1].lower().startswith('year'):
            value = 0.3 if n <= 5 else school_year(n) * 0.9
            if n <= 5 and education and m[1][0].isupper():
                value = 0.7 * n + 1.0
            if not education and n >= 6:
                value *= 0.5
        else:
            value = school_year(n, m[1].lower().startswith('class'))
            if m[1].lower() in {'classes', 'grades'}:
                value *= 0.7
        older_range = re.search(r'ages?\s+(\d{2})\s*(?:to|[-–])', before, re.I)
        if older_range and int(older_range[1]) > 12:
            value = 0.0
    if token == ' ' and re.search(r'\b(?:Class|class|Grade|grade)$', before):
        value = 3.5 if before.lower().endswith('grade') else 4.8
    if word == 'th':
        m = re.search(r'(\d{1,2})$', before)
        if m and 1 <= int(m[1]) <= 12:
            value = 3.8 if education else 0.6
    if token == '8' and re.search(r'\bISBN[\s:-]*97$', before, re.I):
        value = 7.0

    if token in HAN_SCHOOLS:
        value = HAN_SCHOOLS[token]
    if token in {'學', '学'} and before.endswith(('小', '中')):
        value = 4.7
    if token in {'学生', '學生', '学校', '學校'} and before.endswith(('小', '中', '高')):
        value = 4.0
    if re.search(r'(?:初|高)[一二三]$', end):
        value = 7.5 if '初' in end[-2:] else 11.0
        if end.endswith('初一') and re.search(r'[年月]', before[-8:]):
            value = 0.0
    if token in {'级', '級'} and re.search(r'[一二三四五六七八九1-9]年$', before):
        value = 12.0
    if token == '年级' and re.search(r'[一二三四五六七八九1-9]$', before):
        value = 4.0
    if token in {'下', '册'} and re.search(r'年[级級]下?$', before):
        value = 6.5
    if token == '考' and before.endswith(('国', '國', '中', '高')):
        value = 3.2
    return (doc, end[-100:]), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:1847: a "school stage, grade level and exam" detector.

This component is one neuron of layer 1's MLP (its input weight is almost entirely that one
neuron), and it lights up on the word that completes a school-related name or label. It is
silent almost everywhere and very large on a few tokens. The program below predicts it from
the last few tokens only (stateless), with these concepts:

  * school levels: "school" after middle / high / primary / secondary / elementary
    ("high school", "middle school", ~6.5); "junior high", "senior high", "secondary" after
    junior/senior/post (~7); the level word itself is weak (~1);
  * grade labels: a grade number after "Class" / "Grade" ("Class 9", "grade 7", ~6; two-digit
    "Class 1" + "2" ~5); "grad"/"grade" after an ordinal ("sixth grader", ~7); the words
    "Common Core" and "Key Stage" (~5-7); Chinese "五年级" style grade names (~8);
  * curriculum and entrance-exam acronyms, completed by their last piece: NCERT, CBSE, ICSE,
    IGCSE, GCSE, NEET, JEE, IIT, UPSC, EGE (ЕГЭ) (~7); GMAT, whose last piece "AT" follows
    "GM" (~4); GRE and SSC as whole words (~2).

Everything else predicts 0. What it leaves out: the background fluctuation (about 0.1 in size
on most tokens, not predictable from words) and most of the spikes on years, ISBN digits and
other languages. The score is mostly set by the few exam-name and school-stage spikes.
"""
READS = ()

LEVEL = {"middle", "high", "primary", "secondary", "elementary", "junior", "senior",
         "Middle", "High", "Primary", "Secondary", "Elementary", "Junior", "Senior"}
MODIFIER = {"junior", "senior", "Junior", "Senior", "upper", "Upper", "Higher", "higher", "post", "Post"}
SCHOOL = {"school", "School", "schools", "Schools"}
GRADE_LABEL = {"Class", "Grade", "grade", "Grades", "-grade"}
ORDINAL = {"first", "second", "third", "fourth", "fifth", "sixth", "seventh", "eighth", "ninth",
           "tenth", "1st", "2nd", "3rd", "4th", "5th", "6th", "7th", "8th", "9th", "10th"}
EXAM_PIECE = {"NCERT", "CBSE", "ICSE", "IGCSE", "GCSE", "NEET", "JEE", "IIT", "GMAT", "UPSC", "ЕГЭ"}
EXAM_WORD = {"GRE", "SSC"}


def step(carry, prefix, upstream):
    toks = [s.strip() for s in prefix.token_strings]
    w = toks[-1]
    before = [t for t in toks[:-1] if t]          # earlier tokens, skipping spaces
    prev = before[-1] if before else ""
    prev2 = before[-2] if len(before) > 1 else ""
    if not w:                                      # a space right after "Class" or "Grade"
        return carry, 2.0 if prev in GRADE_LABEL else 0.0
    if w in SCHOOL and prev in LEVEL:
        return carry, 6.5
    if w in LEVEL and prev in MODIFIER:
        return carry, 7.0
    if prev + w == "GMAT":
        return carry, 4.0
    if w in EXAM_PIECE or prev + w in EXAM_PIECE or (len(toks) > 1 and toks[-2] == "-" and prev2 + w in EXAM_PIECE):
        return carry, 7.0
    if w in EXAM_WORD:
        return carry, 2.0
    if w.isdigit() and prev in GRADE_LABEL:
        return carry, 6.0
    if w.isdigit() and prev.isdigit() and prev2 in GRADE_LABEL:
        return carry, 5.0
    if w in ("grad", "gr", "grade") and prev in ORDINAL:
        return carry, 7.0
    if w == "Core" and prev == "Common":
        return carry, 5.0
    if w in ("Stage", "stage") and prev == "Key":
        return carry, 7.0
    if w in ("级", "年级") and prev.endswith("年"):
        return carry, 8.0
    if w in GRADE_LABEL:
        return carry, 2.0 if prev[:1].isdigit() or prev in ("th", "st", "nd", "rd") else 1.0
    if w in LEVEL and w not in ("high", "High"):
        return carry, 1.0
    if w in ("school", "School") and prev in ("grade", "Grade"):
        return carry, 2.0
    if w in ("th", "st", "nd", "rd") and prev.isdigit() and any(x in ("grade", "Grade", "Class") for x in before[-3:]):
        return carry, 2.0
    return carry, 0.0

programs.sol:
"""Estimate short word-linking forms rather than sentence boundaries.

Positive cases are dots after initials and likely abbreviations, Romance
elision apostrophes, name-separating middle dots, and incomplete Arabic
article-prefixed fragments. Arabic pieces are joined across token boundaries.
Rare short capitalized words are treated as more likely to be abbreviations.
Repeated middle dots (leaders/padding) receive a negative value.
"""
import math
import re
import unicodedata
import regex
from wordfreq import zipf_frequency

READS = ()
SUN_LETTERS = set('تثدذرزسشصضطظلن')


def arabic_fragment(text, token):
    # Ignore vocalization marks when counting letters of an unfinished word.
    plain = ''.join(c for c in text if unicodedata.category(c) != 'Mn')
    match = regex.search(r'\p{L}+\Z', plain)
    word = match[0] if match else ''
    article = re.match(r'^[وف]?(ال|بال|كال|لل)', word)
    if not article:
        return 0.0
    stem = word[article.end():]
    spaced = token[0].isspace()
    context = text[:-len(token)].rsplit('<|endoftext|>', 1)[-1]
    if not spaced and not regex.search(r'\p{Arabic}', context):
        return 0.0
    if not stem:
        value = {'ال': 5.3, 'بال': 1.8, 'كال': 1.8, 'لل': 2.6}[article[1]]
        if word.startswith(('و', 'ف')):
            value = 4.2 if article[1] == 'ال' else value
        if not spaced:
            value *= 1.6
    elif len(stem) == 1:
        value = 3.8 if stem in SUN_LETTERS else 3.2
        if stem in {'أ', 'آ'}:
            value = 1.6
        elif stem == 'ت':
            value += 1.0  # t- is a productive derived-noun prefix
        if word.startswith(('و', 'ف')):
            value += 0.4
        if not spaced:
            value *= 1.6
    elif stem == 'است' and spaced:
        value = 3.4  # the productive Arabic isti- derivational prefix
    elif len(stem) == 2:
        value = 0.35
        if spaced:
            value = 0.2 if zipf_frequency(word, 'ar') >= 6 else 1.1
            if stem.startswith('ت'):
                value = 2.4
    elif len(stem) == 3:
        value = 0.0
        if spaced:
            value = 0.8 if zipf_frequency(word, 'ar') < 3 else 0.2
    else:
        value = 0.0
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        raw, previous = b'', ''
    else:
        _, raw, previous = carry
    tail = raw.decode('utf-8', 'ignore')
    token = prefix.token_strings[-1]
    raw = (raw + prefix.token_bytes[-1])[-300:]
    value = 0.0
    word = ''
    if token in {'.', "'", '’'}:
        match = re.search(r'([^\W\d_]+)\Z', tail)
        word = match[1] if match else ''
    if token == '.':
        if len(word) == 1:
            if word.isupper():
                value = 0.75 if previous.startswith(' ') else 0.42
                before = re.search(r'([^\W\d_]+) +[^\W\d_]\Z', tail)
                if before:
                    name = before[1]
                    value = 0.95 if name.istitle() and len(name) >= 3 else 0.45
                if tail.split('\n')[-1].strip() in {'A', 'B', 'C', 'D'}:
                    value = 0.0  # answer-choice labels, not personal initials
            elif word.isascii():
                value = 0.16 if previous.startswith(' ') else 0.02
        elif word in {'Mr', 'Mrs', 'Ms', 'Dr'}:
            value = -0.03
        elif word.isascii() and 2 <= len(word) <= 5:
            freq = zipf_frequency(word.lower(), 'en')
            if len(word) == 2:
                value = 0.14 if freq < 6 else 0.02
            elif len(word) <= 4:
                if word.istitle():
                    value = 0.43 / (1 + math.exp(2 * (freq - 4)))
                    if len(word) == 4:
                        value *= 0.8
                elif word.isupper():
                    value = 0.1
                else:
                    value = 0.15 / (1 + math.exp(2 * (freq - 3.5)))
                    if len(word) == 4:
                        value *= 0.4
            elif len(word) == 5 and word.istitle() and freq < 2:
                value = 0.15
    elif token in {"'", '’'}:
        if word in {'l', 'L'}:
            value = 0.85 if word == 'l' else 0.6
        elif word.lower() in {'dell', 'nell', 'all', 'dall', 'sull', 'un'}:
            value = 1.1
        elif word in {'d', 'D'}:
            value = 0.43
        elif len(word) == 1:
            value = 0.05
    elif len(token) >= 2 and not token.strip('·'):
        value = -0.65
    elif token in {'・', '·'}:
        if regex.search(r'[\p{Katakana}ー]\Z', tail):
            value = 1.0
        elif token == '·' and regex.search(r'\p{Han}\Z', tail):
            value = 0.1 if tail.rfind('《') > tail.rfind('》') else 2.0
    elif regex.search(r'\p{Arabic}', token):
        value = arabic_fragment(raw.decode('utf-8', 'ignore'), token)
    return (doc, raw, token), value

"""Recognize descriptions of frequency and counted occasions.

The largest responses are on 'times' after quantities, and 'time' in
phrases such as 'most of the time'. Smaller rules cover frequency adverbs,
ordinal endings, and having seen or heard something. Repeated middle-dot
padding is negative. Literal heading and Java-package cues have separate
responses. Other tokens are zero.
"""
import re
import math
import inflect

READS = ()
_engine = inflect.engine()
NUMBERS = {_engine.number_to_words(n): n for n in range(1, 101)}
NUMBERS.update(hundred=100, thousand=1000, million=1000000,
               billion=1000000000)
ORDINALS = {_engine.ordinal(_engine.number_to_words(n)) for n in range(1, 21)}
QUANTIFIERS = set('many several multiple few numerous countless some'.split())
REPEATS = set('fois veces vezes volte keer'.split())


def response(token, before):
    w = token.strip().lower()
    words = re.findall(r"\w+(?:['’]\w+)*|%", before.lower())
    prev = words[-1] if words else ''
    m = re.search(r'(\d+(?:,\d{3})*(?:\.\d+)?)\s*$', before)
    number = float(m[1].replace(',', '').rstrip('.')) if m else NUMBERS.get(prev)
    if prev.endswith('s') and prev[:-1] in NUMBERS:
        number = NUMBERS[prev[:-1]]
    quantity = number is not None or prev in QUANTIFIERS
    if w in {'times', '-fold', 'fold'}:
        if prev == 'many':
            return 7.8
        if number is not None:
            return 5.1 + min(2.0, 0.65 * math.log10(max(1, number)))
        if prev == 'of':
            return 6.5 if token.strip().islower() else 1.4
        if prev in {'more', 'numerous', 'countless', 'couple', 'consecutive'}:
            return 6.0
        if re.search(r'\b[mnk]\$?\s*$', before) or prev == 'a' and 'many' in words[-3:]:
            return 4.5
        if quantity:
            return 5.5
        if prev in {'often', 'oft'}:
            return 5.8
        return 0.25 if w == 'times' else 0.6
    if w in {'time', '-time'}:
        if re.search(r'(most|much|%|percent)\s+of\s+the\s*$', before.lower()):
            return 9.2
        if re.search(r'(some|all|half|part|rest|[\d])\s+of\s+the\s*$', before.lower()):
            return 5.8
        if re.search(r'\ball\s+the\s*$', before.lower()):
            return 4.5
        if prev in {'whole', 'entire'}:
            return 3.0
        if prev == 'each':
            return 4.1
        if prev == 'every':
            return 2.2
        if prev in ORDINALS:
            return 2.6 if prev == 'first' else 3.8
        if re.search(r'\d+(st|nd|rd|th)\s*$', before):
            return 2.5
        if prev in {'last', 'next'}:
            return 1.7
        if number is not None:
            return 2.0
        if prev == 'more' and len(words) > 1 and words[-2] in NUMBERS:
            return 5.0
        return -0.08
    if w in {'cases', 'instances', 'occasions'}:
        if prev in {'many', 'most', 'numerous'}:
            return 2.8
        if quantity or prev in {'all', 'both', 'other', 'of'}:
            return 1.4
        return 0.12
    if w in {'often', 'oft', 'frequently'}:
        if prev in {'more', 'most', 'less'}:
            return 3.6
        if prev in {'very', 'quite', 'so', 'as', 'how'}:
            return 1.6
        return 0.25
    if w in {'seen', 'heard'}:
        if re.search(r"\bi(?: have|'ve|’ve)(?: \w+){0,2}\s*$", before.lower()):
            return 2.6
        if prev == 'have' or prev.endswith(("'ve", '’ve')):
            return 1.0
        if prev in {'never', 'ever', 'always'} or prev.endswith(("n't", 'n’t')):
            return 1.0
        return 0.05
    if w in REPEATS:
        return 3.5 if quantity else 2.2
    if w in {'次', '倍', '遍', '次数'}:
        counted = number is not None or re.search(r'[二三四五六七八九十百千兩两幾几多]$', before)
        return (1.8 if w == '倍' else 3.0) if counted else 0.2
    if w in {'mal', 'раз'}:
        if quantity:
            return 3.2
        german_count = r'(jedes|manch|noch|dies|ein|erste[nsmr]?|weiteres|anderes)\s*$'
        if re.search(german_count, before.lower()):
            return 2.7
    if w in {'vez', 'volta'}:
        return 1.3
    if w in {'th', 'st', 'nd', 'rd'} and number is not None:
        return 0.4
    if w in {'once', 'twice', 'sometimes', 'never', 'always'}:
        return 0.3
    if w == 'com' and prev == 'package':
        return 2.0
    if token.startswith(':'):
        if prev == 'q':
            return 0.65
        if before.strip().lower() == 'title':
            return 3.6
    if token and set(token) == {'·'} and (not before or before.endswith('·')):
        return -1.43
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, before)
    return (doc, (before + token)[-120:]), value

programs.haiku:
"""How-often words: 'times', 'occasions', 'often', 'twice', French 'fois', ...

The strongest response is to 'times' counting occurrences ('many times', 'three times',
'a number of times', '60 times'). 'time' counts one occurrence in 'the first time',
'each time', 'every time', 'most of the time'; it is near zero in 'the time' used as a
duration, 'at all times' and 'of the time'. Other count and frequency words respond more
weakly.
"""

READS = ()

# how strongly each other frequency word fires (before any context)
FREQUENCY_WORDS = {
    "-fold": 5.2, " fois": 2.6, " volte": 4.0, " volta": 1.6, " vez": 1.3, " lần": 3.3,
    " раз": 0.6, " Mal": 0.8, "次": 1.2, "遍": 1.6, "倍": 0.9, "-time": 0.4,
    " occasions": 1.6, " instances": 0.9, " cases": 0.7, " Times": 1.2,
    " oft": 1.8, " souvent": 2.0, " often": 0.5, " frequently": 0.5, " twice": 0.4,
    " heard": 0.5, " seen": 0.4,
}
# words before 'times' that make it a count ('many times', 'of times', 'three times')
COUNT_BEFORE = {"many", "more", "of", "few", "several", "multiple", "consecutive",
                "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten"}
# words before 'times' that make it a plain noun or idiom ('at all times', 'the times')
NOT_COUNT_BEFORE = {"all", "at", "the", "some", "these", "those", "certain", "good", "relevant"}
# words before 'time' that make it one occurrence, with its typical strength
OCCURRENCE_BEFORE = {"each": 3.5, "every": 2.5, "first": 2.7, "second": 4.0, "third": 4.0,
                     "last": 1.5, "next": 1.6, "final": 3.0, "entire": 4.0, "consecutive": 4.5,
                     "another": 1.5, "single": 1.0, "more": 1.3, "one": 1.3}


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    ids = prefix.document_ids
    word = strings[-1]

    def before(k):
        # the token k places back, or "" at the start of a document
        if len(strings) <= k or ids[-1 - k] != ids[-1]:
            return ""
        return strings[-1 - k].strip().lower()

    prev = before(1)
    if word == " times":
        if prev in COUNT_BEFORE or prev.isdigit():
            return None, 6.5
        return None, 0.2 if prev in NOT_COUNT_BEFORE else 2.0
    if word == " time":
        if prev in OCCURRENCE_BEFORE:
            return None, OCCURRENCE_BEFORE[prev]
        if prev.isdigit():
            return None, 3.0
        if prev == "the" and before(2) == "of":
            # 'most of the time', 'X% of the time' count occurrences; 'of the time' alone does not
            if "most" in (before(3), before(4)) or "%" in (before(3), before(4)):
                return None, 9.0
            return None, 0.0
        return None, 0.4 if prev == "the" else 0.1
    return None, FREQUENCY_WORDS.get(word, 0.0)

programs.sol:
"""A structural approximation to a path/qualified-name continuation signal.

Slashes inside paths produce negative pulses, larger in deep paths and after
long names. Dotted names and word pieces just after separators produce smaller
pulses. Most ordinary text is zero. No token-identity table is used; only the
last 160 characters are retained, and state resets at document boundaries.
"""
import re

READS = ()
CHAIN = re.compile(r'[\w./\\~@:$-]+$')
WORD = re.compile(r'\w+$')
ESCAPES = frozenset(('n', 'r', 't', 'b', 'f', 'v', 'a', '"', "'"))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous = '', ''
    else:
        _, tail, previous = carry
    s = prefix.token_strings[-1]
    match = CHAIN.search(tail)
    chain = match.group().split('://')[-1] if match else ''
    match = WORD.search(tail)
    word_length = len(match.group()) if match else 0
    depth = chain.count('/') + chain.count('\\')
    dots = chain.count('.')
    attached = len(s) > 1
    backslash = s.startswith('\\')
    separator = s.startswith(('/', '\\')) and not s.startswith(('//', '\\\\'))
    separator |= bool(re.fullmatch(r'_+/\s*', s))
    if s.startswith('/') and s[1:2] in ('*', '>', '?', '!'):
        separator = False
    if backslash and s[1:] in ESCAPES:
        separator = False

    value = 0.0
    if separator:
        if depth:
            if backslash:
                value = -0.21
            elif tail and (tail[-1].isalnum() or tail[-1] in '_./\\'):
                if depth >= 6:
                    value = -3.49 if attached else -5.81
                elif word_length >= 6:
                    value = -3.06 if attached else -4.09
                elif depth == 1:
                    value = -0.81 if word_length <= 2 else -2.45
                else:
                    value = -2.87
        elif word_length >= 3 and not backslash:
            value = -0.95
    elif s.startswith('.') and s[1:2].isalpha():
        if dots >= 2:
            value = -1.53
        elif word_length >= 5:
            value = -0.35
    elif s[:1].isalpha():
        if tail.endswith(('/', '\\')) and depth >= 2:
            value = -1.21
        elif previous.startswith(('.', '/', '\\')) and depth + dots >= 2:
            value = -0.33
    return (doc, (tail + s)[-160:], s), value
